"""Command line entry point for quantum-circuit-simulator.

This module is intentionally thin: it owns argument parsing and the
ordering of the three layers, nothing else.

* :mod:`quantum_circuit.preparation` reads files/stdin, decodes UTF-8 and
  parses/validates every input, reporting failures as
  :class:`~quantum_circuit.errors.CommandFailure` data.
* :mod:`quantum_circuit.commands` (with the domain modules
  :mod:`quantum_circuit.core`, :mod:`quantum_circuit.observables`, ...)
  performs the pure computation and assembles success payloads without
  touching files or streams.
* :mod:`quantum_circuit.delivery` writes stdout/stderr and the atomic
  ``--output`` export.
"""

from __future__ import annotations

import argparse
import math
import sys

from . import __version__
from . import commands, preparation
from .delivery import (
    RunContext,
    emit_failure,
    finish,
    output_conflict,
    register_manifest_references,
)
from .documents import json_equal
from .errors import CommandFailure
from .estimation import estimate as estimate_payload
from .simulator import simulate_state_vector  # backwards-compatible CLI name

# Backwards-compatible private alias (exercised by the CLI tests).
_json_equal = json_equal


def _positive_int(value: str) -> int:
    try:
        parsed = int(value, 10)
    except ValueError:
        raise argparse.ArgumentTypeError(f"must be a positive integer, got {value!r}") from None
    if parsed <= 0:
        raise argparse.ArgumentTypeError(f"must be a positive integer, got {parsed}")
    return parsed


def _tolerance(value: str) -> float:
    try:
        parsed = float(value)
    except ValueError:
        raise argparse.ArgumentTypeError(f"must be a finite number between 0 and 1, got {value!r}") from None
    if not math.isfinite(parsed) or not 0.0 <= parsed <= 1.0:
        raise argparse.ArgumentTypeError(f"must be a finite number between 0 and 1, got {value!r}")
    return parsed


def _guard(ctx: RunContext | None) -> int | None:
    """Refuse an input-overwriting export before computation runs."""
    if ctx is None:
        return None
    conflict = output_conflict(ctx)
    if conflict is not None:
        emit_failure(conflict)
        return conflict.exit_code
    return None


def _fail(failure: CommandFailure) -> int:
    emit_failure(failure)
    return failure.exit_code


# --------------------------------------------------------------- simulate etc.


def _simulate(
    source_arg: str,
    shots: int,
    seed: int,
    noise_model_arg: str | None,
    ctx: RunContext | None = None,
) -> int:
    register = ctx.register_input if ctx is not None else None
    program, noise_model, failure = preparation.prepare_simulation(
        source_arg, noise_model_arg, register=register
    )
    if failure is not None:
        return _fail(failure)
    if (code := _guard(ctx)) is not None:
        return code
    try:
        result = commands.simulate_task(program, noise_model, shots, seed)
    except CommandFailure as exc:
        return _fail(exc)
    return finish(ctx, result, 0)


def _probabilities(
    source_arg: str, noise_model_arg: str | None, ctx: RunContext | None = None
) -> int:
    register = ctx.register_input if ctx is not None else None
    program, noise_model, failure = preparation.prepare_simulation(
        source_arg, noise_model_arg, register=register
    )
    if failure is not None:
        return _fail(failure)
    if (code := _guard(ctx)) is not None:
        return code
    try:
        result = commands.probabilities_task(program, noise_model)
    except CommandFailure as exc:
        return _fail(exc)
    return finish(ctx, result, 0)


# --------------------------------------------------------------- verify-samples


def _verify_samples(
    source_arg: str,
    samples_arg: str,
    noise_model_arg: str | None,
    tolerance: float,
    ctx: RunContext | None = None,
) -> int:
    # Three inputs may request standard input; at most one may be '-'. The
    # conflict is detected before any input is read.
    stdin_args = [source_arg, samples_arg]
    if noise_model_arg is not None:
        stdin_args.append(noise_model_arg)
    conflict = commands.stdin_conflict(
        stdin_args,
        "verification_error",
        "at most one of the circuit source, samples document and noise model "
        "can be read from standard input",
    )
    if conflict is not None:
        return _fail(conflict)

    register = ctx.register_input if ctx is not None else None
    # Circuit and noise model use the exact simulate/probabilities path
    # (reading, UTF-8, parsing, validation, model normalization).
    program, noise_model, failure = preparation.prepare_simulation(
        source_arg, noise_model_arg, register=register
    )
    if failure is not None:
        return _fail(failure)

    samples_text, failure = preparation.read_document(
        "samples", "samples", samples_arg, register
    )
    if failure is not None:
        return _fail(failure)

    # The samples document is fully validated against the parsed classical
    # register width before any state is evolved.
    try:
        counts = commands.samples_counts(samples_text, program.num_clbits)
    except CommandFailure as exc:
        return _fail(exc)

    if (code := _guard(ctx)) is not None:
        return code

    try:
        result, exit_code = commands.verify_samples_task(
            program, noise_model, counts, tolerance
        )
    except CommandFailure as exc:
        return _fail(exc)
    return finish(ctx, result, exit_code)


# --------------------------------------------------------------- expectation


def _expectation(
    source_arg: str,
    observables_arg: str,
    noise_model_arg: str | None,
    ctx: RunContext | None = None,
) -> int:
    # Three inputs may request standard input; at most one may be '-'. The
    # conflict is detected before any input is read.
    stdin_args = [source_arg, observables_arg]
    if noise_model_arg is not None:
        stdin_args.append(noise_model_arg)
    conflict = commands.stdin_conflict(
        stdin_args,
        "expectation_error",
        "at most one of the circuit source, observables document and noise model "
        "can be read from standard input",
    )
    if conflict is not None:
        return _fail(conflict)

    register = ctx.register_input if ctx is not None else None
    # Circuit and noise model use the exact simulate/probabilities path
    # (reading, UTF-8, parsing, validation, model normalization).
    program, noise_model, failure = preparation.prepare_simulation(
        source_arg, noise_model_arg, register=register
    )
    if failure is not None:
        return _fail(failure)

    observables_text, failure = preparation.read_document(
        "observables", "observables", observables_arg, register
    )
    if failure is not None:
        return _fail(failure)

    # The observables document is fully validated against the parsed
    # register size before any state is evolved.
    try:
        observables = commands.read_observables(observables_text, program.num_qubits)
    except CommandFailure as exc:
        return _fail(exc)

    if (code := _guard(ctx)) is not None:
        return code

    try:
        result = commands.expectation_task(program, noise_model, observables)
    except CommandFailure as exc:
        return _fail(exc)
    return finish(ctx, result, 0)


# ------------------------------------------------------------- batch-simulate


def _prepare_jobs(jobs, base_dir, register):
    """Read/parse/validate every manifest task, keeping failures as data."""
    prepared = []
    for job in jobs:
        program, noise_model, failure = preparation.prepare_simulation(
            job["source"], job.get("noise_model"), base_dir, register
        )
        embedded = None if failure is None else failure.to_payload()
        prepared.append((program, noise_model, embedded))
    return prepared


def _batch_simulate(manifest_arg: str, ctx: RunContext | None = None) -> int:
    register = ctx.register_input if ctx is not None else None
    manifest_text, _base_dir, failure = preparation.read_batch_manifest(
        manifest_arg, register
    )
    if failure is not None:
        return _fail(failure)

    try:
        jobs = commands.manifest_jobs(manifest_text, "batch_input_error")
    except CommandFailure as exc:
        return _fail(exc)

    # Register every path the validated manifest names, then guard against
    # an input-overwriting export before any task file is opened or any
    # simulation runs. References are registered from the manifest itself,
    # so a missing/unreadable task is still covered.
    if ctx is not None:
        register_manifest_references(ctx, jobs, _base_dir)
        if (code := _guard(ctx)) is not None:
            return code

    # Read, decode, parse and validate every task first (task failures are
    # embedded), then evolve each prepared circuit in manifest order.
    prepared = _prepare_jobs(jobs, _base_dir, register)
    summary, exit_code = commands.run_batch(jobs, prepared)
    return finish(ctx, summary, exit_code)


# --------------------------------------------------------------- reconcile


def _reconcile(manifest_arg: str, baseline_arg: str, ctx: RunContext | None = None) -> int:
    conflict = commands.stdin_conflict(
        [manifest_arg, baseline_arg],
        "reconciliation_error",
        "manifest and baseline cannot both be read from standard input",
    )
    if conflict is not None:
        return _fail(conflict)

    register = ctx.register_input if ctx is not None else None
    # Read and decode both inputs fully (manifest first, then baseline) and
    # validate both before any task file is touched.
    raw_manifest, base_dir, failure = preparation.read_manifest_or_baseline(
        "manifest", manifest_arg, register
    )
    if failure is not None:
        return _fail(failure)
    raw_baseline, _base_dir, failure = preparation.read_manifest_or_baseline(
        "baseline", baseline_arg, register
    )
    if failure is not None:
        return _fail(failure)

    try:
        jobs = commands.manifest_jobs(raw_manifest.decode("utf-8"), "reconcile_input_error")
    except CommandFailure as exc:
        return _fail(exc)
    try:
        baseline_results = commands.baseline_results(raw_baseline.decode("utf-8"), jobs)
    except CommandFailure as exc:
        return _fail(exc)

    # Register every path the validated manifest names (plus the manifest
    # and baseline already read), then guard against an input-overwriting
    # export before any task file is opened or any task is re-run.
    if ctx is not None:
        register_manifest_references(ctx, jobs, base_dir)
        if (code := _guard(ctx)) is not None:
            return code

    # Prepare (read, parse, validate) every task first, then re-run them in
    # manifest order with the exact batch-simulate semantics.
    prepared = _prepare_jobs(jobs, base_dir, register)
    report, exit_code = commands.run_reconcile(jobs, baseline_results, prepared)
    return finish(ctx, report, exit_code)


# ------------------------------------------------------------- optimize etc.


def _optimize(source_arg: str, ctx: RunContext | None = None) -> int:
    register = ctx.register_input if ctx is not None else None
    source, failure = preparation.read_source(source_arg, register)
    if failure is not None:
        return _fail(failure)
    program, failure = preparation.parse_program(source)
    if failure is not None:
        return _fail(failure)
    if (code := _guard(ctx)) is not None:
        return code
    return finish(ctx, commands.optimize_task(program), 0)


def _estimate(source_arg: str, mode: str, ctx: RunContext | None = None) -> int:
    register = ctx.register_input if ctx is not None else None
    source, failure = preparation.read_source(source_arg, register)
    if failure is not None:
        return _fail(failure)
    program, failure = preparation.parse_program(source)
    if failure is not None:
        return _fail(failure)
    if (code := _guard(ctx)) is not None:
        return code
    return finish(ctx, estimate_payload(program, mode), 0)


# --------------------------------------------------------------- equivalent


def _equivalent(left_arg: str, right_arg: str, ctx: RunContext | None = None) -> int:
    conflict = commands.stdin_conflict(
        [left_arg, right_arg],
        "comparison_error",
        "left and right inputs cannot both be read from standard input",
    )
    if conflict is not None:
        return _fail(conflict)

    register = ctx.register_input if ctx is not None else None
    # Fully validate each side (read, parse, semantics, size) in LEFT, RIGHT
    # order, reporting only the first failure.
    left, failure = preparation.load_comparison_program("left", left_arg, register)
    if failure is not None:
        return _fail(failure)
    right, failure = preparation.load_comparison_program("right", right_arg, register)
    if failure is not None:
        return _fail(failure)

    if (code := _guard(ctx)) is not None:
        return code
    return finish(ctx, commands.equivalent_task(left, right), 0)


# ------------------------------------------------------------- state-metrics


def _state_metrics(
    left_arg: str,
    right_arg: str,
    left_noise_arg: str | None,
    right_noise_arg: str | None,
    ctx: RunContext | None = None,
) -> int:
    # The two sources and the two noise models are four stdin-capable
    # inputs; at most one may be '-'. Detect the conflict without touching
    # standard input.
    stdin_values = [left_arg, right_arg]
    if left_noise_arg is not None:
        stdin_values.append(left_noise_arg)
    if right_noise_arg is not None:
        stdin_values.append(right_noise_arg)
    if sum(value == "-" for value in stdin_values) > 1:
        if left_arg == "-" and right_arg == "-":
            # Keep the historical two-source message byte-for-byte.
            message = "left and right inputs cannot both be read from standard input"
        else:
            message = (
                "at most one of the left source, right source, left noise model and "
                "right noise model can be read from standard input"
            )
        emit_failure(CommandFailure("metrics_error", message, 2))
        return 2

    register = ctx.register_input if ctx is not None else None
    # Fully validate in left-source, left-model, right-source, right-model
    # order, reporting only the first failure (each tagged with its side).
    left, failure = preparation.load_program("left", left_arg, register)
    if failure is not None:
        return _fail(failure)
    left_model = None
    if left_noise_arg is not None:
        left_model, failure = preparation.load_metrics_noise_model(
            "left", left_noise_arg, register
        )
        if failure is not None:
            return _fail(failure)

    right, failure = preparation.load_program("right", right_arg, register)
    if failure is not None:
        return _fail(failure)
    right_model = None
    if right_noise_arg is not None:
        right_model, failure = preparation.load_metrics_noise_model(
            "right", right_noise_arg, register
        )
        if failure is not None:
            return _fail(failure)

    if (code := _guard(ctx)) is not None:
        return code

    try:
        result = commands.state_metrics_task(left, right, left_model, right_model)
    except CommandFailure as exc:
        return _fail(exc)
    return finish(ctx, result, 0)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        prog="quantum-circuit-simulator",
        description="Quantum circuit construction, simulation and verification",
    )
    sub = parser.add_subparsers(dest="command")
    sub.add_parser("version", help="print the current version")

    simulate_parser = sub.add_parser("simulate", help="simulate an OpenQASM 2.0 subset circuit")
    simulate_parser.add_argument("source", help="path to the OpenQASM source file, or '-' for stdin")
    simulate_parser.add_argument("--shots", type=_positive_int, default=1024, help="number of samples (default: 1024)")
    simulate_parser.add_argument("--seed", type=int, default=0, help="signed integer RNG seed (default: 0)")
    simulate_parser.add_argument(
        "--noise-model",
        metavar="PATH",
        default=None,
        help="optional JSON noise model for density-matrix simulation ('-' reads stdin)",
    )
    simulate_parser.add_argument(
        "--output",
        metavar="PATH",
        default=None,
        help="write the result JSON line to PATH instead of stdout ('-' is not allowed)",
    )

    probabilities_parser = sub.add_parser(
        "probabilities",
        help="report exact final-state measurement probabilities without sampling",
    )
    probabilities_parser.add_argument(
        "source", help="path to the OpenQASM source file, or '-' for stdin"
    )
    probabilities_parser.add_argument(
        "--noise-model",
        metavar="PATH",
        default=None,
        help="optional JSON noise model for density-matrix probabilities ('-' reads stdin)",
    )
    probabilities_parser.add_argument(
        "--output",
        metavar="PATH",
        default=None,
        help="write the result JSON line to PATH instead of stdout ('-' is not allowed)",
    )

    expectation_parser = sub.add_parser(
        "expectation",
        help="report Pauli-product observable expectation values of the final pre-measurement state",
    )
    expectation_parser.add_argument(
        "source", help="path to the OpenQASM source file, or '-' for stdin"
    )
    expectation_parser.add_argument(
        "observables",
        help="path to the UTF-8 JSON observables document, or '-' for stdin",
    )
    expectation_parser.add_argument(
        "--noise-model",
        metavar="PATH",
        default=None,
        help="optional JSON noise model for density-matrix evolution ('-' reads stdin)",
    )
    expectation_parser.add_argument(
        "--output",
        metavar="PATH",
        default=None,
        help="write the result JSON line to PATH instead of stdout ('-' is not allowed)",
    )

    verify_parser = sub.add_parser(
        "verify-samples",
        help="verify external measurement counts against the exact classical distribution",
    )
    verify_parser.add_argument(
        "source", help="path to the OpenQASM source file, or '-' for stdin"
    )
    verify_parser.add_argument(
        "samples",
        help="path to the UTF-8 JSON samples document, or '-' for stdin",
    )
    verify_parser.add_argument(
        "--noise-model",
        metavar="PATH",
        default=None,
        help="optional JSON noise model for density-matrix probabilities ('-' reads stdin)",
    )
    verify_parser.add_argument(
        "--tolerance",
        metavar="D",
        type=_tolerance,
        default=0.05,
        help="maximum accepted total variation distance, a finite number in [0, 1] (default: 0.05)",
    )
    verify_parser.add_argument(
        "--output",
        metavar="PATH",
        default=None,
        help="write the result JSON line to PATH instead of stdout ('-' is not allowed)",
    )

    equivalent_parser = sub.add_parser(
        "equivalent",
        help="check whether two noiseless OpenQASM circuits implement the same transformation",
    )
    equivalent_parser.add_argument("left", help="path to the left OpenQASM source file, or '-' for stdin")
    equivalent_parser.add_argument("right", help="path to the right OpenQASM source file, or '-' for stdin")
    equivalent_parser.add_argument(
        "--output",
        metavar="PATH",
        default=None,
        help="write the result JSON line to PATH instead of stdout ('-' is not allowed)",
    )

    optimize_parser = sub.add_parser(
        "optimize",
        help="simplify an OpenQASM circuit into a deterministic canonical form",
    )
    optimize_parser.add_argument("source", help="path to the OpenQASM source file, or '-' for stdin")
    optimize_parser.add_argument(
        "--output",
        metavar="PATH",
        default=None,
        help="write the result JSON line to PATH instead of stdout ('-' is not allowed)",
    )

    estimate_parser = sub.add_parser(
        "estimate",
        help="estimate circuit size and feasibility without evolving it",
    )
    estimate_parser.add_argument("source", help="path to the OpenQASM source file, or '-' for stdin")
    estimate_parser.add_argument(
        "--mode",
        choices=("state-vector", "density-matrix", "unitary"),
        default="state-vector",
        help="simulation mode to size (default: state-vector)",
    )
    estimate_parser.add_argument(
        "--output",
        metavar="PATH",
        default=None,
        help="write the result JSON line to PATH instead of stdout ('-' is not allowed)",
    )

    metrics_parser = sub.add_parser(
        "state-metrics",
        help="compare the (optionally noisy) final states of two circuits and measure per-qubit entropy",
    )
    metrics_parser.add_argument("left", help="path to the left OpenQASM source file, or '-' for stdin")
    metrics_parser.add_argument("right", help="path to the right OpenQASM source file, or '-' for stdin")
    metrics_parser.add_argument(
        "--left-noise-model",
        metavar="PATH",
        default=None,
        help="optional JSON noise model for the left circuit ('-' reads stdin)",
    )
    metrics_parser.add_argument(
        "--right-noise-model",
        metavar="PATH",
        default=None,
        help="optional JSON noise model for the right circuit ('-' reads stdin)",
    )
    metrics_parser.add_argument(
        "--output",
        metavar="PATH",
        default=None,
        help="write the result JSON line to PATH instead of stdout ('-' is not allowed)",
    )

    batch_parser = sub.add_parser(
        "batch-simulate",
        help="run a manifest of independent simulations in list order",
    )
    batch_parser.add_argument(
        "manifest",
        help="path to the UTF-8 JSON batch manifest, or '-' for stdin",
    )
    batch_parser.add_argument(
        "--output",
        metavar="PATH",
        default=None,
        help="write the result JSON line to PATH instead of stdout ('-' is not allowed)",
    )

    reconcile_parser = sub.add_parser(
        "reconcile",
        help="re-run a batch manifest and compare against a baseline result file",
    )
    reconcile_parser.add_argument(
        "manifest",
        help="path to the UTF-8 JSON batch manifest, or '-' for stdin",
    )
    reconcile_parser.add_argument(
        "baseline",
        help="path to the UTF-8 JSON batch-simulate result file, or '-' for stdin",
    )
    reconcile_parser.add_argument(
        "--output",
        metavar="PATH",
        default=None,
        help="write the result JSON line to PATH instead of stdout ('-' is not allowed)",
    )

    args = parser.parse_args(argv)

    if args.command == "version":
        print(__version__)
        return 0

    ctx = RunContext(args.output) if getattr(args, "output", None) is not None else None

    if args.command == "simulate":
        return _simulate(args.source, args.shots, args.seed, args.noise_model, ctx)

    if args.command == "probabilities":
        return _probabilities(args.source, args.noise_model, ctx)

    if args.command == "expectation":
        return _expectation(args.source, args.observables, args.noise_model, ctx)

    if args.command == "verify-samples":
        return _verify_samples(args.source, args.samples, args.noise_model, args.tolerance, ctx)

    if args.command == "batch-simulate":
        return _batch_simulate(args.manifest, ctx)

    if args.command == "reconcile":
        return _reconcile(args.manifest, args.baseline, ctx)

    if args.command == "equivalent":
        return _equivalent(args.left, args.right, ctx)

    if args.command == "optimize":
        return _optimize(args.source, ctx)

    if args.command == "estimate":
        return _estimate(args.source, args.mode, ctx)

    if args.command == "state-metrics":
        return _state_metrics(
            args.left,
            args.right,
            args.left_noise_model,
            args.right_noise_model,
            ctx,
        )

    parser.print_help()
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Pure command logic: payload assembly, task execution and orchestration.

Every function here takes already-read and validated inputs (parsed
programs, canonical noise models, parsed JSON documents) and returns the
ready success payload — or raises :class:`~quantum_circuit.errors.CommandFailure`
carrying the stderr error name/message/positions and exit code. Nothing in
this module reads files, standard input or environment, writes streams, or
imports the command entry point, so the complete result-producing logic of
each subcommand can be driven (and tested) without a terminal.

The batch and reconcile commands additionally separate preparation from
execution: their runners take a prebuilt ``prepared`` list whose entries
are ``(program, noise_model, embedded_error)`` triples, where
*embedded_error* is the exact error object embedded for a failed task.
"""

from __future__ import annotations

import json
import math

from .core import (
    SimulationError,
    evolve_basis_probabilities,
    probability_payload,
    run_expectation,
    run_probabilities,
    run_simulation,
    snap_probability,
)
from .documents import (
    BATCH_SCHEMA_VERSION,
    DocumentError,
    json_equal,
    load_json,
    parse_samples_document,
    validate_baseline,
    validate_batch_manifest,
    check_finite_numbers,
)
from .equivalence import (
    EQUIVALENCE_TOLERANCE,
    measurement_layout,
    unitary_distance,
)
from .errors import CommandFailure
from .metrics import (
    density_fidelity,
    density_purity,
    density_single_qubit_entropies,
    normalized_density_matrix,
    pure_density_fidelity,
    single_qubit_entropies,
    state_fidelity,
)
from .noise import MAX_NOISE_QUBITS, evolve_density_matrix
from .observables import (
    ObservableError,
    parse_observables,
)
from .optimizer import optimize as optimize_program
from .simulator import simulate_state_vector, unitary_matrix

PreparedTask = tuple[object, dict[str, float] | None, dict[str, object] | None]


# ----------------------------------------------------------- shared mappers


def read_observables(text: str, num_qubits: int):
    """Parse the observables document, mapping :class:`ObservableError`."""
    try:
        return parse_observables(text, num_qubits)
    except ObservableError as exc:
        raise CommandFailure("observable_error", str(exc), 2) from None


def samples_counts(text: str, num_clbits: int) -> dict[str, int]:
    """Validate the samples document, mapping its error name/exit code."""
    try:
        return parse_samples_document(text, num_clbits)
    except DocumentError as exc:
        raise CommandFailure("sample_input_error", str(exc), 2) from None


def manifest_jobs(text: str, error_name: str) -> list[dict[str, object]]:
    """Parse a batch manifest for *error_name* (batch or reconcile)."""
    try:
        data = load_json(text, "batch manifest")
        return validate_batch_manifest(data)
    except json.JSONDecodeError as exc:
        raise CommandFailure(error_name, f"batch manifest is not valid JSON: {exc}", 2) from None
    except DocumentError as exc:
        raise CommandFailure(error_name, str(exc), 2) from None


def baseline_results(text: str, jobs: list[dict[str, object]]) -> list[dict[str, object]]:
    """Parse and validate a reconcile baseline against the manifest jobs."""
    try:
        data = load_json(text, "baseline")
        check_finite_numbers(data, "baseline")
        return validate_baseline(data, jobs)
    except json.JSONDecodeError as exc:
        raise CommandFailure("reconcile_input_error", f"baseline is not valid JSON: {exc}", 2) from None
    except DocumentError as exc:
        raise CommandFailure("reconcile_input_error", str(exc), 2) from None


def stdin_conflict(values: list[str], error_name: str, message: str) -> CommandFailure | None:
    """Return the standard-input conflict failure when more than one is '-'."""
    if sum(value == "-" for value in values) > 1:
        return CommandFailure(error_name, message, 2)
    return None


# ------------------------------------------------------------- single tasks


def simulate_task(
    program,
    noise_model: dict[str, float] | None,
    shots: int,
    seed: int,
) -> dict[str, object]:
    """Sample one prepared circuit (the ``simulate`` success payload)."""
    try:
        return run_simulation(program, shots, seed, noise_model)
    except SimulationError as exc:
        raise CommandFailure("simulation_error", str(exc), 3) from None


def probabilities_task(program, noise_model: dict[str, float] | None) -> dict[str, object]:
    """Exact distribution payload (``probabilities``)."""
    try:
        return run_probabilities(program, noise_model)
    except SimulationError as exc:
        raise CommandFailure("simulation_error", str(exc), 3) from None


def verify_samples_task(
    program,
    noise_model: dict[str, float] | None,
    counts: dict[str, int],
    tolerance: float,
) -> tuple[dict[str, object], int]:
    """Assemble the verify-samples report; exit code 3 when rejected."""
    try:
        basis_probabilities = evolve_basis_probabilities(program, noise_model)
    except SimulationError as exc:
        raise CommandFailure("simulation_error", str(exc), 3) from None

    # Expected probabilities follow the exact ``probabilities`` convention
    # (aggregation, renormalization, near-zero/near-one snapping).
    expected = probability_payload(program, basis_probabilities, noise_model)["probabilities"]
    assert isinstance(expected, dict)

    shots = sum(counts.values())
    observed: dict[str, float] = {}
    for key in sorted(counts):
        snapped = snap_probability(counts[key] / shots)
        if snapped is not None:
            observed[key] = snapped

    # Total variation distance over the union of both distributions' keys;
    # outcomes absent from either side contribute probability zero.
    keys = set(expected) | set(observed)
    distance = 0.5 * math.fsum(
        abs(expected.get(key, 0.0) - observed.get(key, 0.0)) for key in keys
    )
    accepted = distance <= tolerance

    result: dict[str, object] = {
        "schema_version": 1,
        "num_qubits": program.num_qubits,
        "num_clbits": program.num_clbits,
        "shots": shots,
        "noise_model": noise_model,
        "tolerance": tolerance,
        "total_variation_distance": distance,
        "accepted": accepted,
        "expected_probabilities": expected,
        "observed_probabilities": observed,
    }
    return result, 0 if accepted else 3


def expectation_task(
    program,
    noise_model: dict[str, float] | None,
    observables: list[tuple[str, list[tuple[int, str]]]],
) -> dict[str, object]:
    """Evaluate every observable against the final (pre-measurement) state."""
    try:
        return run_expectation(program, noise_model, observables)
    except SimulationError as exc:
        raise CommandFailure("simulation_error", str(exc), 3) from None


def equivalent_task(left, right) -> dict[str, object]:
    """Compare two prepared, size-checked noiseless circuits."""
    left_qubits = left.num_qubits
    right_qubits = right.num_qubits

    left_clbits, left_measurements = measurement_layout(left)
    right_clbits, right_measurements = measurement_layout(right)

    if left_qubits != right_qubits:
        return {
            "schema_version": 1,
            "equivalent": False,
            "reason": "qubit_count_mismatch",
            "left_num_qubits": left_qubits,
            "right_num_qubits": right_qubits,
            "distance": None,
            "tolerance": EQUIVALENCE_TOLERANCE,
        }

    distance = unitary_distance(unitary_matrix(left), unitary_matrix(right))

    same_transform = distance <= EQUIVALENCE_TOLERANCE
    same_layout = left_clbits == right_clbits and left_measurements == right_measurements

    if not same_transform:
        reason = "unitary_distance"
        equivalent = False
    elif not same_layout:
        reason = "measurement_layout_mismatch"
        equivalent = False
    else:
        reason = "equivalent"
        equivalent = True

    return {
        "schema_version": 1,
        "equivalent": equivalent,
        "reason": reason,
        "left_num_qubits": left_qubits,
        "right_num_qubits": right_qubits,
        "distance": distance,
        "tolerance": EQUIVALENCE_TOLERANCE,
    }


def optimize_task(program) -> dict[str, object]:
    """Simplify one prepared circuit into its canonical payload."""
    original_gate_count = sum(1 for op in program.operations if op.kind != "measure")
    gates, changed, qasm = optimize_program(program)
    return {
        "schema_version": 1,
        "num_qubits": program.num_qubits,
        "num_clbits": program.num_clbits,
        "original_gate_count": original_gate_count,
        "optimized_gate_count": len(gates),
        "changed": changed,
        "qasm": qasm,
    }


def state_metrics_task(left, right, left_model, right_model) -> dict[str, object]:
    """Compare the final states of two prepared (optionally noisy) circuits."""
    # A noisy side evolves a full density matrix (at most MAX_NOISE_QUBITS);
    # a model-less side keeps the 20-qubit state-vector path.
    if left_model is not None and left.num_qubits > MAX_NOISE_QUBITS:
        raise CommandFailure(
            "simulation_error",
            f"noise simulation supports at most {MAX_NOISE_QUBITS} qubits, "
            f"left input has {left.num_qubits}",
            3,
            side="left",
        ) from None
    if right_model is not None and right.num_qubits > MAX_NOISE_QUBITS:
        raise CommandFailure(
            "simulation_error",
            f"noise simulation supports at most {MAX_NOISE_QUBITS} qubits, "
            f"right input has {right.num_qubits}",
            3,
            side="right",
        ) from None

    noisy = left_model is not None or right_model is not None

    left_state: list[complex] | None = None
    right_state: list[complex] | None = None
    left_rho: list[list[complex]] | None = None
    right_rho: list[list[complex]] | None = None
    if left_model is None:
        left_state = simulate_state_vector(left)
    else:
        left_rho = normalized_density_matrix(evolve_density_matrix(left, left_model))
    if right_model is None:
        right_state = simulate_state_vector(right)
    else:
        right_rho = normalized_density_matrix(evolve_density_matrix(right, right_model))

    same_qubits = left.num_qubits == right.num_qubits
    reason = "compared" if same_qubits else "qubit_count_mismatch"

    if not same_qubits:
        fidelity: float | None = None
    elif left_rho is None and right_rho is None:
        fidelity = state_fidelity(left_state, right_state)
    elif left_rho is not None and right_rho is not None:
        fidelity = density_fidelity(left_rho, right_rho)
    elif left_rho is not None:
        fidelity = pure_density_fidelity(right_state, left_rho)
    else:
        fidelity = pure_density_fidelity(left_state, right_rho)

    left_purity = 1.0 if left_rho is None else density_purity(left_rho)
    right_purity = 1.0 if right_rho is None else density_purity(right_rho)
    left_entropy = (
        single_qubit_entropies(left_state, left.num_qubits)
        if left_rho is None
        else density_single_qubit_entropies(left_rho, left.num_qubits)
    )
    right_entropy = (
        single_qubit_entropies(right_state, right.num_qubits)
        if right_rho is None
        else density_single_qubit_entropies(right_rho, right.num_qubits)
    )

    if not noisy:
        # No noise model on either side: keep the schema_version 1 payload
        # byte-for-byte identical to the historical command.
        return {
            "schema_version": 1,
            "left_num_qubits": left.num_qubits,
            "right_num_qubits": right.num_qubits,
            "reason": reason,
            "fidelity": fidelity,
            "left_single_qubit_entropy": left_entropy,
            "right_single_qubit_entropy": right_entropy,
        }
    return {
        "schema_version": 2,
        "left_num_qubits": left.num_qubits,
        "right_num_qubits": right.num_qubits,
        "reason": reason,
        "left_noise_model": left_model,
        "right_noise_model": right_model,
        "fidelity": fidelity,
        "left_purity": left_purity,
        "right_purity": right_purity,
        "left_single_qubit_entropy": left_entropy,
        "right_single_qubit_entropy": right_entropy,
    }


# ------------------------------------------------------------- batch runners


def _task_output(
    program,
    noise_model: dict[str, float] | None,
    shots: int,
    seed: int,
) -> tuple[dict[str, object] | None, dict[str, object] | None]:
    """Sample one task, converting only the simulation failure to payload."""
    try:
        return run_simulation(program, shots, seed, noise_model), None
    except SimulationError as exc:
        return None, CommandFailure("simulation_error", str(exc), 3).to_payload()


def run_batch(
    jobs: list[dict[str, object]],
    prepared: list[PreparedTask],
) -> tuple[dict[str, object], int]:
    """Execute prepared tasks in manifest order (failures embedded)."""
    results: list[dict[str, object]] = []
    succeeded = 0
    for job, (program, noise_model, prepare_error) in zip(jobs, prepared):
        output: dict[str, object] | None = None
        error = prepare_error
        if error is None:
            output, error = _task_output(
                program,
                noise_model,
                job.get("shots", 1024),
                job.get("seed", 0),
            )
        if error is None:
            succeeded += 1
            results.append({"id": job["id"], "status": "succeeded", "output": output})
        else:
            results.append({"id": job["id"], "status": "failed", "error": error})

    summary: dict[str, object] = {
        "schema_version": BATCH_SCHEMA_VERSION,
        "job_count": len(jobs),
        "succeeded": succeeded,
        "failed": len(jobs) - succeeded,
        "results": results,
    }
    return summary, 0 if succeeded == len(jobs) else 3


def run_reconcile(
    jobs: list[dict[str, object]],
    baseline: list[dict[str, object]],
    prepared: list[PreparedTask],
) -> tuple[dict[str, object], int]:
    """Re-run prepared tasks and diff them against the validated baseline."""
    entries: list[dict[str, object]] = []
    matched = 0
    for job, (program, noise_model, prepare_error), reference in zip(jobs, prepared, baseline):
        output: dict[str, object] | None = None
        error = prepare_error
        if error is None:
            output, error = _task_output(
                program,
                noise_model,
                job.get("shots", 1024),
                job.get("seed", 0),
            )
        current: dict[str, object] = (
            {"id": job["id"], "status": "succeeded", "output": output}
            if error is None
            else {"id": job["id"], "status": "failed", "error": error}
        )
        entry: dict[str, object] = {"id": job["id"]}
        if current["status"] != reference["status"]:
            entry["consistent"] = False
            entry["reason"] = "status_mismatch"
            entry["expected"] = reference
            entry["actual"] = current
            entries.append(entry)
            continue

        if current["status"] == "succeeded":
            equal = json_equal(reference["output"], output)
            reason = "output_mismatch"
        else:
            equal = json_equal(reference["error"], error)
            reason = "error_mismatch"

        if equal:
            entry["consistent"] = True
            entry["reason"] = "identical"
            matched += 1
        else:
            entry["consistent"] = False
            entry["reason"] = reason
            # Preserve the complete baseline and current task result.
            entry["expected"] = reference
            entry["actual"] = current
        entries.append(entry)

    mismatched = len(jobs) - matched
    report: dict[str, object] = {
        "schema_version": BATCH_SCHEMA_VERSION,
        "job_count": len(jobs),
        "matched": matched,
        "mismatched": mismatched,
        "consistent": mismatched == 0,
        "results": entries,
    }
    return report, 0 if mismatched == 0 else 3

"""Input preparation for the command layer.

This is the only layer that touches the file system and standard input.
Each helper reads and decodes one input, then parses and validates it,
returning either the prepared value or a
:class:`~quantum_circuit.errors.CommandFailure` whose name, message,
positions, ``input`` side and exit code match the historical commands
exactly. Helpers never write standard streams, so the validation order
(read errors, UTF-8 errors, parse errors, semantic errors) is expressed as
plain data flow and remains unit-testable.

Paths inside batch manifests are resolved relative to *base_dir* while
error messages keep quoting the user-supplied path verbatim, exactly as a
standalone invocation would.
"""

from __future__ import annotations

import os
import sys

from .errors import CommandFailure
from .equivalence import MAX_EQUIVALENCE_QUBITS
from .noise import NoiseModelError, parse_noise_model
from .openqasm import ParseError, Program, ValidationError, parse


def _resolve(path: str, base_dir: str | None) -> str:
    if base_dir is not None and not os.path.isabs(path):
        return os.path.normpath(os.path.join(base_dir, path))
    return path


def _read_bytes(path: str, base_dir: str | None) -> bytes:
    """Read raw bytes from *path* (resolved against *base_dir*) or stdin."""
    if path == "-":
        return sys.stdin.buffer.read()
    with open(_resolve(path, base_dir), "rb") as handle:
        return handle.read()


def _read_text(
    path: str,
    base_dir: str | None,
    error_name: str,
    noun: str,
    *,
    utf8_error: str | None = None,
    side: str | None = None,
) -> tuple[str | None, CommandFailure | None]:
    """Read and UTF-8 decode one document.

    *noun* is how the input is quoted in messages (e.g. ``"source"``,
    ``"samples"``, ``"noise model"``). An unreadable file is *error_name*
    (typically ``io_error``); an invalid UTF-8 document is *utf8_error*
    when given (noise models use ``noise_model_error``), otherwise the
    same *error_name*.
    """
    try:
        data = _read_bytes(path, base_dir)
    except OSError as exc:
        return None, CommandFailure(
            error_name, f"cannot read {noun} {path!r}: {exc.strerror or exc}", 1, side=side
        )
    try:
        return data.decode("utf-8"), None
    except UnicodeDecodeError as exc:
        return None, CommandFailure(
            utf8_error or error_name,
            f"{noun} {path!r} is not valid UTF-8: {exc}",
            2 if utf8_error is not None else 1,
            side=side,
        )


def prepare_simulation(
    source_arg: str,
    noise_model_arg: str | None,
    base_dir: str | None = None,
    register=None,
) -> tuple[Program | None, dict[str, float] | None, CommandFailure | None]:
    """Read, decode, parse and validate one simulation input.

    Returns ``(program, noise_model, failure)``: on success *failure* is
    ``None`` (with *noise_model* ``None`` on the state-vector path); on
    failure *program* is ``None``. Reading (files, UTF-8, ``-`` for stdin,
    relative paths) and error semantics match ``simulate`` for both
    ``simulate`` and ``probabilities``. No qubit-limit or simulation error
    is raised here; callers apply their own limits.

    When *base_dir* is given (the batch case), relative paths are opened
    relative to it while error messages keep quoting *source_arg* and
    *noise_model_arg* verbatim.
    """
    if noise_model_arg is not None and source_arg == "-" and noise_model_arg == "-":
        return (
            None,
            None,
            CommandFailure(
                "noise_model_error",
                "circuit source and noise model cannot both be read from standard input",
                2,
            ),
        )

    try:
        data = _read_bytes(source_arg, base_dir)
    except OSError as exc:
        return None, None, CommandFailure(
            "io_error", f"cannot read source {source_arg!r}: {exc.strerror or exc}", 1
        )
    if register is not None:
        register(source_arg, base_dir)

    try:
        source = data.decode("utf-8")
    except UnicodeDecodeError as exc:
        return None, None, CommandFailure(
            "io_error", f"source {source_arg!r} is not valid UTF-8: {exc}", 1
        )

    noise_model: dict[str, float] | None = None
    if noise_model_arg is not None:
        # An unreadable model is io_error; invalid UTF-8 or bad content is
        # noise_model_error (the historical two-tier behavior).
        try:
            raw_model = _read_bytes(noise_model_arg, base_dir)
        except OSError as exc:
            return (
                None,
                None,
                CommandFailure(
                    "io_error",
                    f"cannot read noise model {noise_model_arg!r}: {exc.strerror or exc}",
                    1,
                ),
            )
        if register is not None:
            register(noise_model_arg, base_dir)
        try:
            model_text = raw_model.decode("utf-8")
        except UnicodeDecodeError as exc:
            return (
                None,
                None,
                CommandFailure(
                    "noise_model_error",
                    f"noise model {noise_model_arg!r} is not valid UTF-8: {exc}",
                    2,
                ),
            )
        try:
            noise_model = parse_noise_model(model_text)
        except NoiseModelError as exc:
            return None, None, CommandFailure("noise_model_error", str(exc), 2)

    try:
        program = parse(source)
    except ParseError as exc:
        return None, None, CommandFailure(
            "parse_error", exc.message, 2, line=exc.line, column=exc.column
        )
    except ValidationError as exc:
        return None, None, CommandFailure(
            "validation_error", exc.message, 2, line=exc.line, column=exc.column
        )

    return program, noise_model, None


def read_document(
    side: str, noun: str, arg: str, register=None
) -> tuple[str | None, CommandFailure | None]:
    """Read a UTF-8 auxiliary JSON document (samples/observables) or stdin.

    *side* is reported verbatim in the ``input`` field on every failure.
    """
    text, failure = _read_text(arg, None, "io_error", noun, side=side)
    if failure is None and register is not None:
        register(arg, None)
    return text, failure


def read_source(
    source_arg: str, register=None
) -> tuple[str | None, CommandFailure | None]:
    """Read a UTF-8 circuit source from a path or ``-`` (stdin)."""
    text, failure = _read_text(source_arg, None, "io_error", "source")
    if failure is None and register is not None:
        register(source_arg, None)
    return text, failure


def parse_program(source: str) -> tuple[Program | None, CommandFailure | None]:
    """Parse/validate one circuit source into a program or a failure."""
    try:
        program = parse(source)
    except ParseError as exc:
        return None, CommandFailure(
            "parse_error", exc.message, 2, line=exc.line, column=exc.column
        )
    except ValidationError as exc:
        return None, CommandFailure(
            "validation_error", exc.message, 2, line=exc.line, column=exc.column
        )
    return program, None


def load_program(
    side: str, source_arg: str, register=None
) -> tuple[Program | None, CommandFailure | None]:
    """Read, parse and validate one side of a two-circuit comparison.

    *side* (``"left"``/``"right"``) is reported as ``input`` on every
    failure. Returns the parsed :class:`Program` or a failure.
    """
    source, failure = _read_text(source_arg, None, "io_error", "source", side=side)
    if failure is not None:
        return None, failure
    program, failure = parse_program(source)
    if program is None:
        # Tag the parse/validation failure with the comparison side.
        assert failure is not None
        return None, CommandFailure(
            failure.error,
            failure.message,
            failure.exit_code,
            side=side,
            line=failure.line,
            column=failure.column,
        )
    if register is not None:
        register(source_arg, None)
    return program, None


def load_comparison_program(
    side: str, source_arg: str, register=None
) -> tuple[Program | None, CommandFailure | None]:
    """Load one equivalence side, additionally enforcing the 8-qubit cap."""
    program, failure = load_program(side, source_arg, register)
    if program is None:
        return None, failure
    if program.num_qubits > MAX_EQUIVALENCE_QUBITS:
        return None, CommandFailure(
            "simulation_error",
            f"equivalence comparison supports at most {MAX_EQUIVALENCE_QUBITS} qubits, "
            f"{side} input has {program.num_qubits}",
            3,
            side=side,
        )
    return program, None


def load_metrics_noise_model(
    side: str, model_arg: str, register=None
) -> tuple[dict[str, float] | None, CommandFailure | None]:
    """Read and validate one side's ``state-metrics`` noise model.

    Mirrors the ``simulate`` model handling but tags every failure with
    *side* (``"left"``/``"right"``).
    """
    try:
        raw_model = _read_bytes(model_arg, None)
    except OSError as exc:
        return None, CommandFailure(
            "io_error",
            f"cannot read noise model {model_arg!r}: {exc.strerror or exc}",
            1,
            side=side,
        )
    if register is not None:
        register(model_arg, None)
    try:
        model_text = raw_model.decode("utf-8")
    except UnicodeDecodeError as exc:
        return None, CommandFailure(
            "noise_model_error",
            f"noise model {model_arg!r} is not valid UTF-8: {exc}",
            2,
            side=side,
        )
    try:
        return parse_noise_model(model_text), None
    except NoiseModelError as exc:
        return None, CommandFailure("noise_model_error", str(exc), 2, side=side)


def read_manifest_or_baseline(
    side: str, arg: str, register=None
) -> tuple[bytes | None, str | None, CommandFailure | None]:
    """Read one reconcile-style input, returning raw bytes and base dir.

    *side* is ``"manifest"`` or ``"baseline"``. Standard input resolves
    *base_dir* to the current working directory; a path resolves it to
    the file's own directory. Bytes are UTF-8 checked but returned raw so
    the caller owns JSON error naming.
    """
    try:
        if arg == "-":
            raw = sys.stdin.buffer.read()
            base_dir = os.getcwd()
        else:
            with open(arg, "rb") as handle:
                raw = handle.read()
            base_dir = os.path.dirname(os.path.abspath(arg))
    except OSError as exc:
        return None, None, CommandFailure(
            "io_error", f"cannot read {side} {arg!r}: {exc.strerror or exc}", 1, side=side
        )
    try:
        raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        return None, None, CommandFailure(
            "io_error", f"{side} {arg!r} is not valid UTF-8: {exc}", 1, side=side
        )
    if register is not None and arg != "-":
        register(arg, None)
    return raw, base_dir, None


def read_batch_manifest(
    manifest_arg: str, register=None
) -> tuple[str | None, str | None, CommandFailure | None]:
    """Read and UTF-8 decode a batch-simulate manifest (path or stdin)."""
    if manifest_arg == "-":
        try:
            raw_manifest = sys.stdin.buffer.read()
        except OSError as exc:
            return None, None, CommandFailure(
                "io_error", f"cannot read manifest {manifest_arg!r}: {exc.strerror or exc}", 1
            )
        base_dir = os.getcwd()
    else:
        try:
            with open(manifest_arg, "rb") as handle:
                raw_manifest = handle.read()
        except OSError as exc:
            return None, None, CommandFailure(
                "io_error", f"cannot read manifest {manifest_arg!r}: {exc.strerror or exc}", 1
            )
        base_dir = os.path.dirname(os.path.abspath(manifest_arg))
    if register is not None:
        register(manifest_arg, None)
    try:
        return raw_manifest.decode("utf-8"), base_dir, None
    except UnicodeDecodeError as exc:
        return None, None, CommandFailure(
            "io_error", f"manifest {manifest_arg!r} is not valid UTF-8: {exc}", 1
        )

"""Python DSL for building circuits over the OpenQASM 2.0 subset.

A :class:`Circuit` is created with a quantum and a classical register size
and extended by chaining gate and measurement methods, mirroring the
statements of the supported OpenQASM subset one to one::

    circuit = Circuit(2, 2).h(0).cx(0, 1).measure(0, 0).measure(1, 1)

Operations keep their insertion order and every chaining method returns the
same circuit object. The circuit renders to (:meth:`Circuit.to_qasm`) and
parses from (:meth:`Circuit.from_qasm`) the OpenQASM 2.0 subset text the
command line accepts, and simulates through the exact code paths of the
``simulate``, ``probabilities`` and ``expectation`` commands
(:meth:`Circuit.sample`, :meth:`Circuit.probabilities`,
:meth:`Circuit.expectation`), so the returned dictionaries match the
commands' JSON objects field by field.

Validation mirrors the parser's semantic rules: type mismatches raise
:class:`TypeError`, while out-of-range indices, non-finite angles and
semantic conflicts (control equal to target, repeated measurement, a gate
after a measurement) raise :class:`ValueError`. A rejected operation never
changes the circuit.
"""

from __future__ import annotations

import math
from collections.abc import Mapping

from .core import SimulationError, run_expectation, run_probabilities, run_simulation
from .gates import (
    Operation,
    gate_operation,
    gate_qasm,
    measurement_operation,
)
from .noise import validate_noise_model
from .observables import MAX_OBSERVABLES
from .openqasm import Program, parse

# Register sizes accepted by the DSL match the parser's limit.
_MIN_REGISTER_SIZE = 1
_MAX_REGISTER_SIZE = 20

_DEFAULT_SHOTS = 1024
_DEFAULT_SEED = 0


def _check_register_size(name: str, value: object) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(
            f"{name} must be an integer, got {type(value).__name__}"
        )
    if not _MIN_REGISTER_SIZE <= value <= _MAX_REGISTER_SIZE:
        raise ValueError(
            f"{name} must be between {_MIN_REGISTER_SIZE} and {_MAX_REGISTER_SIZE}, got {value}"
        )
    return value


def _check_index(register: str, value: object, size: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(
            f"{register} index must be an integer, got {type(value).__name__}"
        )
    if not 0 <= value < size:
        raise ValueError(
            f"{register} index {value} out of range for register of size {size}"
        )
    return value


def _check_angle(value: object) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(
            f"angle must be an integer or float, got {type(value).__name__}"
        )
    angle = float(value)
    if not math.isfinite(angle):
        raise ValueError("angle must be a finite number")
    return angle


def _operation_line(op: Operation) -> str:
    """Render one operation as an OpenQASM statement (register names q/c)."""
    if op.kind == "measure":
        return f"measure q[{op.targets[0]}] -> c[{op.targets[1]}];"
    return gate_qasm(op.kind, op.targets, op.params[0] if op.params else None)


_OBSERVABLE_KEYS = ("id", "operators")
_OPERATOR_KEYS = ("qubit", "pauli")
_PAULIS = ("X", "Y", "Z")


def _check_observable_operators(
    operators: object, where: str, num_qubits: int
) -> list[tuple[int, str]]:
    if isinstance(operators, bool) or not isinstance(operators, (list, tuple)):
        raise TypeError(
            f"{where} 'operators' must be a list or tuple, "
            f"got {type(operators).__name__}"
        )
    parsed: list[tuple[int, str]] = []
    seen_qubits: set[int] = set()
    for op_index, operator in enumerate(operators):
        op_where = f"{where}.operators[{op_index}]"
        if not isinstance(operator, Mapping):
            raise TypeError(
                f"{op_where} must be a mapping, got {type(operator).__name__}"
            )
        for key in operator:
            if key not in _OPERATOR_KEYS:
                raise ValueError(f"{op_where} has unknown field {key!r}")

        if "qubit" not in operator:
            raise ValueError(f"{op_where} is missing required field 'qubit'")
        qubit = operator["qubit"]
        if isinstance(qubit, bool) or not isinstance(qubit, int):
            raise TypeError(
                f"{op_where} 'qubit' must be an integer, "
                f"got {type(qubit).__name__}"
            )
        if not 0 <= qubit < num_qubits:
            raise ValueError(
                f"{op_where} 'qubit' {qubit} out of range for register of "
                f"size {num_qubits}"
            )
        if qubit in seen_qubits:
            raise ValueError(f"{op_where} repeats qubit {qubit} within {where}")
        seen_qubits.add(qubit)

        if "pauli" not in operator:
            raise ValueError(f"{op_where} is missing required field 'pauli'")
        pauli = operator["pauli"]
        if not isinstance(pauli, str):
            raise TypeError(
                f"{op_where} 'pauli' must be a string, got {type(pauli).__name__}"
            )
        if pauli not in _PAULIS:
            raise ValueError(
                f"{op_where} 'pauli' must be one of 'X', 'Y', 'Z', got {pauli!r}"
            )

        parsed.append((qubit, pauli))
    return parsed


def _check_observables(
    observables: object, num_qubits: int
) -> list[tuple[str, list[tuple[int, str]]]]:
    """Validate one observables batch, returning ``(id, operators)`` pairs.

    Type mismatches raise :class:`TypeError`; size, field, identifier,
    qubit and Pauli violations raise :class:`ValueError`. The whole batch
    is checked before any state evolution happens.
    """
    if isinstance(observables, bool) or not isinstance(observables, (list, tuple)):
        raise TypeError(
            f"observables must be a list or tuple, got {type(observables).__name__}"
        )
    if not 1 <= len(observables) <= MAX_OBSERVABLES:
        raise ValueError(
            f"observables must contain between 1 and {MAX_OBSERVABLES} entries, "
            f"got {len(observables)}"
        )

    parsed: list[tuple[str, list[tuple[int, str]]]] = []
    seen_ids: set[str] = set()
    for index, item in enumerate(observables):
        where = f"observables[{index}]"
        if not isinstance(item, Mapping):
            raise TypeError(f"{where} must be a mapping, got {type(item).__name__}")
        for key in item:
            if key not in _OBSERVABLE_KEYS:
                raise ValueError(f"{where} has unknown field {key!r}")

        if "id" not in item:
            raise ValueError(f"{where} is missing required field 'id'")
        observable_id = item["id"]
        if not isinstance(observable_id, str):
            raise TypeError(
                f"{where} 'id' must be a string, got {type(observable_id).__name__}"
            )
        if not observable_id:
            raise ValueError(f"{where} 'id' must be a non-empty string")
        if observable_id in seen_ids:
            raise ValueError(f"duplicate observable id {observable_id!r}")
        seen_ids.add(observable_id)

        if "operators" not in item:
            raise ValueError(f"{where} is missing required field 'operators'")
        parsed.append(
            (
                observable_id,
                _check_observable_operators(item["operators"], where, num_qubits),
            )
        )
    return parsed


class Circuit:
    """A quantum circuit over the supported OpenQASM 2.0 subset.

    Created with the quantum and classical register sizes (integers from 1
    to 20, booleans rejected) and extended through the chaining gate and
    measurement methods, which return the circuit itself.
    """

    def __init__(self, num_qubits: int, num_clbits: int):
        self._num_qubits = _check_register_size("num_qubits", num_qubits)
        self._num_clbits = _check_register_size("num_clbits", num_clbits)
        self._operations: list[Operation] = []
        self._measured_qubits: set[int] = set()
        self._measured_clbits: set[int] = set()
        self._measurement_started = False

    # ------------------------------------------------------------ properties

    @property
    def num_qubits(self) -> int:
        return self._num_qubits

    @property
    def num_clbits(self) -> int:
        return self._num_clbits

    @property
    def operations(self) -> tuple[Operation, ...]:
        """The appended operations, in insertion order."""
        return tuple(self._operations)

    def __repr__(self) -> str:
        return (
            f"Circuit(num_qubits={self._num_qubits}, num_clbits={self._num_clbits}, "
            f"operations={len(self._operations)})"
        )

    # ------------------------------------------------------------------ gates

    def _qubit_index(self, value: object) -> int:
        return _check_index("qubit", value, self._num_qubits)

    def _clbit_index(self, value: object) -> int:
        return _check_index("clbit", value, self._num_clbits)

    def _check_gate_allowed(self, kind: str) -> None:
        if self._measurement_started:
            raise ValueError(f"quantum gate {kind!r} cannot be added after a measurement")

    def _append_gate(self, op: Operation) -> Circuit:
        # All validation has already happened in the calling method, so a
        # rejected operation never reaches this point and never mutates the
        # circuit.
        self._operations.append(op)
        return self

    def _fixed_single_gate(self, name: str, qubit: object) -> Circuit:
        target = self._qubit_index(qubit)
        self._check_gate_allowed(name)
        return self._append_gate(gate_operation(name, (target,)))

    def _controlled_gate(self, name: str, control: object, target: object) -> Circuit:
        ctrl = self._qubit_index(control)
        tgt = self._qubit_index(target)
        if ctrl == tgt:
            raise ValueError(f"{name} control and target must be different qubits")
        self._check_gate_allowed(name)
        return self._append_gate(gate_operation(name, (ctrl, tgt)))

    def _swap_gate(self, first: object, second: object) -> Circuit:
        a = self._qubit_index(first)
        b = self._qubit_index(second)
        if a == b:
            raise ValueError("swap operands must be different qubits")
        self._check_gate_allowed("swap")
        return self._append_gate(gate_operation("swap", (a, b)))

    def _rotation_gate(self, name: str, angle: object, qubit: object) -> Circuit:
        theta = _check_angle(angle)
        target = self._qubit_index(qubit)
        self._check_gate_allowed(name)
        return self._append_gate(gate_operation(name, (target,), (theta,)))

    def _controlled_rotation_gate(
        self, name: str, angle: object, control: object, target: object
    ) -> Circuit:
        theta = _check_angle(angle)
        ctrl = self._qubit_index(control)
        tgt = self._qubit_index(target)
        if ctrl == tgt:
            raise ValueError(f"{name} control and target must be different qubits")
        self._check_gate_allowed(name)
        return self._append_gate(gate_operation(name, (ctrl, tgt), (theta,)))

    def x(self, qubit: int) -> Circuit:
        """Append an ``x`` gate on *qubit*."""
        return self._fixed_single_gate("x", qubit)

    def h(self, qubit: int) -> Circuit:
        """Append an ``h`` gate on *qubit*."""
        return self._fixed_single_gate("h", qubit)

    def y(self, qubit: int) -> Circuit:
        """Append a ``y`` gate on *qubit*."""
        return self._fixed_single_gate("y", qubit)

    def z(self, qubit: int) -> Circuit:
        """Append a ``z`` gate on *qubit*."""
        return self._fixed_single_gate("z", qubit)

    def s(self, qubit: int) -> Circuit:
        """Append an ``s`` gate on *qubit*."""
        return self._fixed_single_gate("s", qubit)

    def sdg(self, qubit: int) -> Circuit:
        """Append an ``sdg`` gate on *qubit*."""
        return self._fixed_single_gate("sdg", qubit)

    def t(self, qubit: int) -> Circuit:
        """Append a ``t`` gate on *qubit*."""
        return self._fixed_single_gate("t", qubit)

    def tdg(self, qubit: int) -> Circuit:
        """Append a ``tdg`` gate on *qubit*."""
        return self._fixed_single_gate("tdg", qubit)

    def cx(self, control: int, target: int) -> Circuit:
        """Append a ``cx`` gate from *control* to *target*."""
        return self._controlled_gate("cx", control, target)

    def cz(self, control: int, target: int) -> Circuit:
        """Append a ``cz`` gate from *control* to *target*."""
        return self._controlled_gate("cz", control, target)

    def swap(self, first: int, second: int) -> Circuit:
        """Append a ``swap`` gate exchanging *first* and *second*."""
        return self._swap_gate(first, second)

    def rx(self, angle: float, qubit: int) -> Circuit:
        """Append an ``rx(angle)`` gate on *qubit* (angle in radians)."""
        return self._rotation_gate("rx", angle, qubit)

    def ry(self, angle: float, qubit: int) -> Circuit:
        """Append an ``ry(angle)`` gate on *qubit* (angle in radians)."""
        return self._rotation_gate("ry", angle, qubit)

    def rz(self, angle: float, qubit: int) -> Circuit:
        """Append an ``rz(angle)`` gate on *qubit* (angle in radians)."""
        return self._rotation_gate("rz", angle, qubit)

    def crx(self, angle: float, control: int, target: int) -> Circuit:
        """Append a ``crx(angle)`` gate from *control* to *target*."""
        return self._controlled_rotation_gate("crx", angle, control, target)

    def cry(self, angle: float, control: int, target: int) -> Circuit:
        """Append a ``cry(angle)`` gate from *control* to *target*."""
        return self._controlled_rotation_gate("cry", angle, control, target)

    def crz(self, angle: float, control: int, target: int) -> Circuit:
        """Append a ``crz(angle)`` gate from *control* to *target*."""
        return self._controlled_rotation_gate("crz", angle, control, target)

    # ------------------------------------------------------------ measurement

    def measure(self, qubit: int, clbit: int) -> Circuit:
        """Append ``measure qubit -> clbit``.

        Each qubit and each clbit may take part in at most one measurement,
        and no quantum gate may be added once measurement has started.
        """
        q = self._qubit_index(qubit)
        c = self._clbit_index(clbit)
        if q in self._measured_qubits:
            raise ValueError(f"qubit {q} is measured more than once")
        if c in self._measured_clbits:
            raise ValueError(f"clbit {c} is the target of more than one measurement")
        self._measured_qubits.add(q)
        self._measured_clbits.add(c)
        self._measurement_started = True
        self._operations.append(measurement_operation(q, c))
        return self

    # --------------------------------------------------------------- OpenQASM

    def to_qasm(self) -> str:
        """Render the circuit as OpenQASM 2.0 subset text.

        Uses the fixed register names ``q`` and ``c``, emits the operations
        in insertion order with the same statement semantics as the parser,
        and ends with a trailing newline. Angles use the shortest decimal
        representation that round-trips to the same float (negative zero is
        written as ``0``).
        """
        lines = [
            "OPENQASM 2.0;",
            'include "qelib1.inc";',
            f"qreg q[{self._num_qubits}];",
            f"creg c[{self._num_clbits}];",
        ]
        lines.extend(_operation_line(op) for op in self._operations)
        return "\n".join(lines) + "\n"

    @classmethod
    def from_qasm(cls, source: str) -> Circuit:
        """Build a circuit from OpenQASM 2.0 subset text.

        Parsing and validation are exactly those of the command line:
        :class:`~quantum_circuit.openqasm.ParseError` and
        :class:`~quantum_circuit.openqasm.ValidationError` propagate with
        their 1-based line/column positions intact.
        """
        if not isinstance(source, str):
            raise TypeError(f"source must be a string, got {type(source).__name__}")
        program = parse(source)
        circuit = cls(program.num_qubits, program.num_clbits)
        for op in program.operations:
            # The program is fully validated, so these invariants hold.
            if op.kind == "measure":
                circuit._measured_qubits.add(op.targets[0])
                circuit._measured_clbits.add(op.targets[1])
                circuit._measurement_started = True
            circuit._operations.append(op)
        return circuit

    # -------------------------------------------------------------- simulation

    def _to_program(self) -> Program:
        return Program(self._num_qubits, self._num_clbits, tuple(self._operations))

    @staticmethod
    def _prepare_noise_model(noise_model: object) -> dict[str, float] | None:
        if noise_model is None:
            return None
        return validate_noise_model(noise_model)

    def sample(self, shots: int = _DEFAULT_SHOTS, seed: int = _DEFAULT_SEED, noise_model=None) -> dict:
        """Sample the circuit, returning the ``simulate`` payload as a dict.

        The result equals the JSON object the ``simulate`` command produces
        for :meth:`to_qasm` with the same *shots*, *seed* and noise model
        (defaults 1024 and 0). *noise_model* is a mapping with the four
        optional channels; invalid models raise
        :class:`~quantum_circuit.noise.NoiseModelError`. Each call samples
        from a fresh RNG seeded by *seed*, so repeated calls with equal
        arguments return equal results and no random state is shared. The
        circuit itself is never modified.
        """
        if isinstance(shots, bool) or not isinstance(shots, int):
            raise TypeError(f"shots must be an integer, got {type(shots).__name__}")
        if shots <= 0:
            raise ValueError(f"shots must be a positive integer, got {shots}")
        if isinstance(seed, bool) or not isinstance(seed, int):
            raise TypeError(f"seed must be an integer, got {type(seed).__name__}")
        model = self._prepare_noise_model(noise_model)
        program = self._to_program()
        try:
            return run_simulation(program, shots, seed, model)
        except SimulationError as exc:
            # The DSL reports the noisy size limit as a ValueError, matching
            # its other value-range errors rather than the CLI's exit code 3.
            raise ValueError(str(exc)) from None

    def probabilities(self, noise_model=None) -> dict:
        """Exact final-state measurement probabilities, as a dict.

        The result equals the JSON object the ``probabilities`` command
        produces for :meth:`to_qasm` with the same noise model. The circuit
        itself is never modified.
        """
        model = self._prepare_noise_model(noise_model)
        program = self._to_program()
        try:
            return run_probabilities(program, model)
        except SimulationError as exc:
            raise ValueError(str(exc)) from None

    def expectation(self, observables, noise_model=None) -> dict:
        """Pauli-product expectation values of the final pre-measurement state.

        *observables* is a list or tuple of 1 to 100 mappings, each with an
        ``id`` (a non-empty string, unique within the batch) and
        ``operators`` (a list or tuple of mappings with a ``qubit`` — a
        non-boolean integer inside the quantum register, not repeated
        within one entry — and a ``pauli`` of ``"X"``, ``"Y"`` or
        ``"Z"``). An empty ``operators`` sequence is the global identity.
        Type mismatches raise :class:`TypeError`; size, field, identifier,
        qubit and Pauli violations raise :class:`ValueError`, and the whole
        batch is validated before any state evolution happens.

        The result equals the JSON object the ``expectation`` command
        produces for :meth:`to_qasm` with the equivalent observables
        document and the same noise model, keeping the input order:
        ``schema_version``, ``num_qubits``, ``noise_model`` (``None``
        without a model) and ``results``, each result carrying the original
        ``id`` and its ``expectation`` in ``[-1, 1]``. Measurement mappings
        and the classical register width do not take part. Invalid noise
        models raise :class:`~quantum_circuit.noise.NoiseModelError`; a
        noisy circuit beyond the density-matrix qubit limit raises
        :class:`ValueError`. Repeated calls with equal arguments return
        equal results, and neither the circuit nor *observables* is
        modified.
        """
        parsed = _check_observables(observables, self._num_qubits)
        model = self._prepare_noise_model(noise_model)
        program = self._to_program()
        try:
            return run_expectation(program, model, parsed)
        except SimulationError as exc:
            raise ValueError(str(exc)) from None


__all__ = ["Circuit"]

"""State-vector simulation and deterministic shot sampling."""

from __future__ import annotations

import cmath
import math
import random

from .gates import (
    PHASE_FACTORS,
    Operation,
    rotation_matrix,
)
from .openqasm import Program

_SQRT1_2 = 2.0**-0.5


def _hadamard(state: list[complex], qubit: int, num_qubits: int) -> None:
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            a = state[low]
            b = state[high]
            state[low] = (a + b) * _SQRT1_2
            state[high] = (a - b) * _SQRT1_2


def _pauli_x(state: list[complex], qubit: int, num_qubits: int) -> None:
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            state[low], state[high] = state[high], state[low]


def _pauli_y(state: list[complex], qubit: int, num_qubits: int) -> None:
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            a = state[low]
            b = state[high]
            state[low] = -1j * b
            state[high] = 1j * a


# Phase gates diag(1, phase): z, s/sdg (diag(1, +-i)) and t/tdg
# (phase exp(+-i*pi/4)). The factors come from the single gate registry so
# the state-vector path cannot diverge from the density/unitary matrices.
_PHASE_GATES = PHASE_FACTORS


def _phase(state: list[complex], qubit: int, num_qubits: int, factor: complex) -> None:
    bit = 1 << qubit
    for index in range(1 << num_qubits):
        if index & bit:
            state[index] = factor * state[index]


def _swap(state: list[complex], first: int, second: int, num_qubits: int) -> None:
    first_bit = 1 << first
    second_bit = 1 << second
    for index in range(1 << num_qubits):
        if (index & first_bit) and not (index & second_bit):
            other = (index ^ first_bit) | second_bit
            state[index], state[other] = state[other], state[index]


def _controlled_x(state: list[complex], control: int, target: int, num_qubits: int) -> None:
    cbit = 1 << control
    tbit = 1 << target
    for index in range(1 << num_qubits):
        if (index & cbit) and not (index & tbit):
            other = index | tbit
            if index < other:
                state[index], state[other] = state[other], state[index]


def _controlled_single(
    state: list[complex],
    control: int,
    target: int,
    num_qubits: int,
    matrix: tuple[complex, complex, complex, complex],
) -> None:
    """Apply a single-qubit matrix to *target* where the *control* bit is 1."""
    g00, g01, g10, g11 = matrix
    cbit = 1 << control
    tbit = 1 << target
    step = tbit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + tbit):
            if not (low & cbit):
                continue
            high = low | tbit
            a = state[low]
            b = state[high]
            state[low] = g00 * a + g01 * b
            state[high] = g10 * a + g11 * b


def _rx(state: list[complex], qubit: int, num_qubits: int, theta: float) -> None:
    c = math.cos(theta / 2)
    s = math.sin(theta / 2)
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            a = state[low]
            b = state[high]
            state[low] = c * a - 1j * s * b
            state[high] = -1j * s * a + c * b


def _ry(state: list[complex], qubit: int, num_qubits: int, theta: float) -> None:
    c = math.cos(theta / 2)
    s = math.sin(theta / 2)
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            a = state[low]
            b = state[high]
            state[low] = c * a - s * b
            state[high] = s * a + c * b


def _rz(state: list[complex], qubit: int, num_qubits: int, theta: float) -> None:
    lo_factor = cmath.exp(-0.5j * theta)
    hi_factor = cmath.exp(0.5j * theta)
    bit = 1 << qubit
    for index in range(1 << num_qubits):
        if index & bit:
            state[index] = hi_factor * state[index]
        else:
            state[index] = lo_factor * state[index]


def _apply_gate(state: list[complex], op: Operation, num_qubits: int) -> None:
    """Apply one (non-measurement) *op* to *state* in place.

    The dispatch uses the gate's registered style and the single shared
    matrix expression in :mod:`quantum_circuit.gates`; only the numeric
    state-vector kernels below are local to this module.
    """
    kind = op.kind
    if kind == "x":
        _pauli_x(state, op.targets[0], num_qubits)
    elif kind == "h":
        _hadamard(state, op.targets[0], num_qubits)
    elif kind == "y":
        _pauli_y(state, op.targets[0], num_qubits)
    elif kind in _PHASE_GATES:
        _phase(state, op.targets[0], num_qubits, _PHASE_GATES[kind])
    elif kind == "swap":
        _swap(state, op.targets[0], op.targets[1], num_qubits)
    elif kind == "cx":
        _controlled_x(state, op.targets[0], op.targets[1], num_qubits)
    elif kind == "cz":
        _controlled_single(
            state, op.targets[0], op.targets[1], num_qubits, op.spec.target_unitary()
        )
    elif kind in ("rx", "ry", "rz"):
        axis = op.spec.axis
        if axis == "x":
            _rx(state, op.targets[0], num_qubits, op.params[0])
        elif axis == "y":
            _ry(state, op.targets[0], num_qubits, op.params[0])
        else:
            _rz(state, op.targets[0], num_qubits, op.params[0])
    else:
        # Controlled angle rotations crx/cry/crz: the target embedding is
        # the one matrix definition shared with the density path.
        matrix = rotation_matrix(op.spec.axis, op.params[0])
        _controlled_single(state, op.targets[0], op.targets[1], num_qubits, matrix)


def simulate_state_vector(program: Program) -> list[complex]:
    """Return the final state vector after applying all quantum gates.

    Basis-state integer ``k`` stores qubit ``i`` in bit ``i`` (q[0] is the
    least significant bit). Measurements do not collapse the state: the spec
    guarantees every measurement comes after every gate and each qubit is
    measured at most once, so non-destructive sampling of the final state is
    equivalent.
    """
    n = program.num_qubits
    state = [0j] * (1 << n)
    state[0] = 1 + 0j

    for op in program.operations:
        if op.kind == "measure":
            # Measurements affect only the sampled classical outcomes.
            continue
        _apply_gate(state, op, n)
    return state


def unitary_matrix(program: Program) -> list[list[complex]]:
    """Return the full unitary U induced by the gates (pre-measurement).

    The matrix acts on basis vectors with qubit ``i`` in bit ``i`` (q[0] is
    the least significant bit), matching :func:`simulate_state_vector`.
    Measurement operations are ignored. Columns are evolved independently by
    applying each gate in source order, so for a circuit with gates G1..Gk the
    result is U = Gk @ ... @ G1.
    """
    n = program.num_qubits
    dim = 1 << n
    gate_ops = [op for op in program.operations if op.kind != "measure"]

    columns: list[list[complex]] = []
    for start in range(dim):
        state = [0j] * dim
        state[start] = 1 + 0j
        for op in gate_ops:
            _apply_gate(state, op, n)
        columns.append(state)

    # Transpose columns-of-U into rows.
    return [[columns[col][row] for col in range(dim)] for row in range(dim)]


def measurement_probabilities(program: Program, basis_probabilities: list[float]) -> dict[str, float]:
    """Aggregate basis-state probabilities into classical-outcome probabilities.

    Uses the same qubit-to-clbit mapping as :func:`sample_counts` (each
    measured qubit contributes its bit to the classical index; unwritten
    clbits stay 0) and the same fixed-width, lexicographically ordered key
    convention. With no measurements the only possible outcome is the
    all-zero string, carrying total probability 1.
    """
    width = program.num_clbits
    measurements = [(op.targets[0], op.targets[1]) for op in program.operations if op.kind == "measure"]

    if not measurements:
        return {format(0, f"0{width}b") if width else "": 1.0}

    aggregated: dict[int, float] = {}
    for basis, probability in enumerate(basis_probabilities):
        classical = 0
        for qubit, clbit in measurements:
            if (basis >> qubit) & 1:
                classical |= 1 << clbit
        aggregated[classical] = aggregated.get(classical, 0.0) + probability

    return {
        format(classical, f"0{width}b") if width else "": probability
        for classical, probability in sorted(aggregated.items())
    }


def sample_counts(program: Program, state: list[complex], shots: int, seed: int) -> dict[str, int]:
    """Draw *shots* samples from *state* deterministically from *seed*.

    Returns a mapping from fixed-width classical bit strings (highest clbit
    index first) to occurrence counts. Only observed outcomes are present.
    """
    probabilities = [abs(amplitude) ** 2 for amplitude in state]
    return sample_counts_from_probabilities(program, probabilities, shots, seed)


def sample_counts_from_probabilities(
    program: Program, probabilities: list[float], shots: int, seed: int
) -> dict[str, int]:
    """Draw *shots* samples from explicit basis-state probabilities.

    Used by the density-matrix path, which supplies the diagonal of the
    final density matrix; sampling semantics match the state-vector path.
    """
    measurements = [(op.targets[0], op.targets[1]) for op in program.operations if op.kind == "measure"]

    total = sum(probabilities)
    cumulative = []
    running = 0.0
    for probability in probabilities:
        running += probability / total
        cumulative.append(running)
    if cumulative:
        cumulative[-1] = 1.0

    rng = random.Random(seed)
    width = program.num_clbits
    counts: dict[str, int] = {}
    for _ in range(shots):
        point = rng.random()
        # Binary search for the first cumulative value >= point.
        lo, hi = 0, len(cumulative)
        while lo < hi:
            mid = (lo + hi) // 2
            if cumulative[mid] < point:
                lo = mid + 1
            else:
                hi = mid
        basis = lo

        classical = 0
        for qubit, clbit in measurements:
            if (basis >> qubit) & 1:
                classical |= 1 << clbit
        key = format(classical, f"0{width}b") if width else ""
        counts[key] = counts.get(key, 0) + 1

    return dict(sorted(counts.items()))

"""Input preparation for the command layer.

This is the only layer that touches the file system and standard input.
Each helper reads and decodes one input, then parses and validates it,
returning either the prepared value or a
:class:`~quantum_circuit.errors.CommandFailure` whose name, message,
positions, ``input`` side and exit code match the historical commands
exactly. Helpers never write standard streams, so the validation order
(read errors, UTF-8 errors, parse errors, semantic errors) is expressed as
plain data flow and remains unit-testable.

Paths inside batch manifests are resolved relative to *base_dir* while
error messages keep quoting the user-supplied path verbatim, exactly as a
standalone invocation would.
"""

from __future__ import annotations

import os
import sys

from .errors import CommandFailure
from .equivalence import MAX_EQUIVALENCE_QUBITS
from .noise import NoiseModelError, parse_noise_model
from .openqasm import ParseError, Program, ValidationError, parse


def _resolve(path: str, base_dir: str | None) -> str:
    if base_dir is not None and not os.path.isabs(path):
        return os.path.normpath(os.path.join(base_dir, path))
    return path


def _read_bytes(path: str, base_dir: str | None) -> bytes:
    """Read raw bytes from *path* (resolved against *base_dir*) or stdin."""
    if path == "-":
        return sys.stdin.buffer.read()
    with open(_resolve(path, base_dir), "rb") as handle:
        return handle.read()


def _read_text(
    path: str,
    base_dir: str | None,
    error_name: str,
    noun: str,
    *,
    utf8_error: str | None = None,
    side: str | None = None,
) -> tuple[str | None, CommandFailure | None]:
    """Read and UTF-8 decode one document.

    *noun* is how the input is quoted in messages (e.g. ``"source"``,
    ``"samples"``, ``"noise model"``). An unreadable file is *error_name*
    (typically ``io_error``); an invalid UTF-8 document is *utf8_error*
    when given (noise models use ``noise_model_error``), otherwise the
    same *error_name*.
    """
    try:
        data = _read_bytes(path, base_dir)
    except OSError as exc:
        return None, CommandFailure(
            error_name, f"cannot read {noun} {path!r}: {exc.strerror or exc}", 1, side=side
        )
    try:
        return data.decode("utf-8"), None
    except UnicodeDecodeError as exc:
        return None, CommandFailure(
            utf8_error or error_name,
            f"{noun} {path!r} is not valid UTF-8: {exc}",
            2 if utf8_error is not None else 1,
            side=side,
        )


def prepare_simulation(
    source_arg: str,
    noise_model_arg: str | None,
    base_dir: str | None = None,
    register=None,
) -> tuple[Program | None, dict[str, float] | None, CommandFailure | None]:
    """Read, decode, parse and validate one simulation input.

    Returns ``(program, noise_model, failure)``: on success *failure* is
    ``None`` (with *noise_model* ``None`` on the state-vector path); on
    failure *program* is ``None``. Reading (files, UTF-8, ``-`` for stdin,
    relative paths) and error semantics match ``simulate`` for both
    ``simulate`` and ``probabilities``. No qubit-limit or simulation error
    is raised here; callers apply their own limits.

    When *base_dir* is given (the batch case), relative paths are opened
    relative to it while error messages keep quoting *source_arg* and
    *noise_model_arg* verbatim.
    """
    if noise_model_arg is not None and source_arg == "-" and noise_model_arg == "-":
        return (
            None,
            None,
            CommandFailure(
                "noise_model_error",
                "circuit source and noise model cannot both be read from standard input",
                2,
            ),
        )

    try:
        data = _read_bytes(source_arg, base_dir)
    except OSError as exc:
        return None, None, CommandFailure(
            "io_error", f"cannot read source {source_arg!r}: {exc.strerror or exc}", 1
        )
    if register is not None:
        register(source_arg, base_dir)

    try:
        source = data.decode("utf-8")
    except UnicodeDecodeError as exc:
        return None, None, CommandFailure(
            "io_error", f"source {source_arg!r} is not valid UTF-8: {exc}", 1
        )

    noise_model: dict[str, float] | None = None
    if noise_model_arg is not None:
        # An unreadable model is io_error; invalid UTF-8 or bad content is
        # noise_model_error (the historical two-tier behavior).
        try:
            raw_model = _read_bytes(noise_model_arg, base_dir)
        except OSError as exc:
            return (
                None,
                None,
                CommandFailure(
                    "io_error",
                    f"cannot read noise model {noise_model_arg!r}: {exc.strerror or exc}",
                    1,
                ),
            )
        if register is not None:
            register(noise_model_arg, base_dir)
        try:
            model_text = raw_model.decode("utf-8")
        except UnicodeDecodeError as exc:
            return (
                None,
                None,
                CommandFailure(
                    "noise_model_error",
                    f"noise model {noise_model_arg!r} is not valid UTF-8: {exc}",
                    2,
                ),
            )
        try:
            noise_model = parse_noise_model(model_text)
        except NoiseModelError as exc:
            return None, None, CommandFailure("noise_model_error", str(exc), 2)

    try:
        program = parse(source)
    except ParseError as exc:
        return None, None, CommandFailure(
            "parse_error", exc.message, 2, line=exc.line, column=exc.column
        )
    except ValidationError as exc:
        return None, None, CommandFailure(
            "validation_error", exc.message, 2, line=exc.line, column=exc.column
        )

    return program, noise_model, None


def read_document(
    side: str, noun: str, arg: str, register=None
) -> tuple[str | None, CommandFailure | None]:
    """Read a UTF-8 auxiliary JSON document (samples/observables) or stdin.

    *side* is reported verbatim in the ``input`` field on every failure.
    """
    text, failure = _read_text(arg, None, "io_error", noun, side=side)
    if failure is None and register is not None:
        register(arg, None)
    return text, failure


def read_source(
    source_arg: str, register=None
) -> tuple[str | None, CommandFailure | None]:
    """Read a UTF-8 circuit source from a path or ``-`` (stdin)."""
    text, failure = _read_text(source_arg, None, "io_error", "source")
    if failure is None and register is not None:
        register(source_arg, None)
    return text, failure


def parse_program(source: str) -> tuple[Program | None, CommandFailure | None]:
    """Parse/validate one circuit source into a program or a failure."""
    try:
        program = parse(source)
    except ParseError as exc:
        return None, CommandFailure(
            "parse_error", exc.message, 2, line=exc.line, column=exc.column
        )
    except ValidationError as exc:
        return None, CommandFailure(
            "validation_error", exc.message, 2, line=exc.line, column=exc.column
        )
    return program, None


def load_program(
    side: str, source_arg: str, register=None
) -> tuple[Program | None, CommandFailure | None]:
    """Read, parse and validate one side of a two-circuit comparison.

    *side* (``"left"``/``"right"``) is reported as ``input`` on every
    failure. Returns the parsed :class:`Program` or a failure.
    """
    source, failure = _read_text(source_arg, None, "io_error", "source", side=side)
    if failure is not None:
        return None, failure
    program, failure = parse_program(source)
    if program is None:
        # Tag the parse/validation failure with the comparison side.
        assert failure is not None
        return None, CommandFailure(
            failure.error,
            failure.message,
            failure.exit_code,
            side=side,
            line=failure.line,
            column=failure.column,
        )
    if register is not None:
        register(source_arg, None)
    return program, None


def load_comparison_program(
    side: str, source_arg: str, register=None
) -> tuple[Program | None, CommandFailure | None]:
    """Load one equivalence side, additionally enforcing the 8-qubit cap."""
    program, failure = load_program(side, source_arg, register)
    if program is None:
        return None, failure
    if program.num_qubits > MAX_EQUIVALENCE_QUBITS:
        return None, CommandFailure(
            "simulation_error",
            f"equivalence comparison supports at most {MAX_EQUIVALENCE_QUBITS} qubits, "
            f"{side} input has {program.num_qubits}",
            3,
            side=side,
        )
    return program, None


def load_metrics_noise_model(
    side: str, model_arg: str, register=None
) -> tuple[dict[str, float] | None, CommandFailure | None]:
    """Read and validate one side's ``state-metrics`` noise model.

    Mirrors the ``simulate`` model handling but tags every failure with
    *side* (``"left"``/``"right"``).
    """
    try:
        raw_model = _read_bytes(model_arg, None)
    except OSError as exc:
        return None, CommandFailure(
            "io_error",
            f"cannot read noise model {model_arg!r}: {exc.strerror or exc}",
            1,
            side=side,
        )
    if register is not None:
        register(model_arg, None)
    try:
        model_text = raw_model.decode("utf-8")
    except UnicodeDecodeError as exc:
        return None, CommandFailure(
            "noise_model_error",
            f"noise model {model_arg!r} is not valid UTF-8: {exc}",
            2,
            side=side,
        )
    try:
        return parse_noise_model(model_text), None
    except NoiseModelError as exc:
        return None, CommandFailure("noise_model_error", str(exc), 2, side=side)


def read_manifest_or_baseline(
    side: str, arg: str, register=None
) -> tuple[bytes | None, str | None, CommandFailure | None]:
    """Read one reconcile-style input, returning raw bytes and base dir.

    *side* is ``"manifest"`` or ``"baseline"``. Standard input resolves
    *base_dir* to the current working directory; a path resolves it to
    the file's own directory. Bytes are UTF-8 checked but returned raw so
    the caller owns JSON error naming.
    """
    try:
        if arg == "-":
            raw = sys.stdin.buffer.read()
            base_dir = os.getcwd()
        else:
            with open(arg, "rb") as handle:
                raw = handle.read()
            base_dir = os.path.dirname(os.path.abspath(arg))
    except OSError as exc:
        return None, None, CommandFailure(
            "io_error", f"cannot read {side} {arg!r}: {exc.strerror or exc}", 1, side=side
        )
    try:
        raw.decode("utf-8")
    except UnicodeDecodeError as exc:
        return None, None, CommandFailure(
            "io_error", f"{side} {arg!r} is not valid UTF-8: {exc}", 1, side=side
        )
    if register is not None and arg != "-":
        register(arg, None)
    return raw, base_dir, None


def read_batch_manifest(
    manifest_arg: str, register=None
) -> tuple[str | None, str | None, CommandFailure | None]:
    """Read and UTF-8 decode a batch-simulate manifest (path or stdin)."""
    if manifest_arg == "-":
        try:
            raw_manifest = sys.stdin.buffer.read()
        except OSError as exc:
            return None, None, CommandFailure(
                "io_error", f"cannot read manifest {manifest_arg!r}: {exc.strerror or exc}", 1
            )
        base_dir = os.getcwd()
    else:
        try:
            with open(manifest_arg, "rb") as handle:
                raw_manifest = handle.read()
        except OSError as exc:
            return None, None, CommandFailure(
                "io_error", f"cannot read manifest {manifest_arg!r}: {exc.strerror or exc}", 1
            )
        base_dir = os.path.dirname(os.path.abspath(manifest_arg))
    if register is not None:
        register(manifest_arg, None)
    try:
        return raw_manifest.decode("utf-8"), base_dir, None
    except UnicodeDecodeError as exc:
        return None, None, CommandFailure(
            "io_error", f"manifest {manifest_arg!r} is not valid UTF-8: {exc}", 1
        )

"""Pure validation for the JSON document inputs (samples, manifests, baselines).

The command layer only reads bytes and decodes UTF-8; every syntactic,
structural, type and range rule for the auxiliary JSON documents lives
here, operating on text or already-parsed values. Nothing in this module
touches the file system, standard input or the standard streams, so the
rules can be exercised independently of the command entry point.

The three document families share strict-JSON conventions (duplicate keys
and ``NaN``/``Infinity`` constants are rejected, booleans never stand in
for integers); :func:`load_json` centralizes them and each family supplies
its own structural validator.
"""

from __future__ import annotations

import json
import math

from .noise import MAX_NOISE_QUBITS

BATCH_SCHEMA_VERSION = 1
MAX_BATCH_JOBS = 100

_VERIFY_SAMPLES_ROOT_KEYS = ("schema_version", "counts")
_BATCH_ROOT_KEYS = ("schema_version", "jobs")
_BATCH_JOB_KEYS = ("id", "source", "shots", "seed", "noise_model")

_BASELINE_ROOT_KEYS = ("schema_version", "job_count", "succeeded", "failed", "results")
_BASELINE_RESULT_KEYS = ("id", "status", "output", "error")
_OUTPUT_V1_KEYS = ("schema_version", "shots", "seed", "num_qubits", "num_clbits", "counts")
_OUTPUT_V2_KEYS = (
    "schema_version",
    "shots",
    "seed",
    "num_qubits",
    "num_clbits",
    "noise_model",
    "counts",
)
_NOISE_CHANNELS = ("amplitude_damping", "phase_damping", "bit_flip", "depolarizing")
_ERROR_KEYS = ("error", "message", "line", "column")
_RECONCILE_ERROR_NAMES = (
    "io_error",
    "parse_error",
    "validation_error",
    "noise_model_error",
    "simulation_error",
)
# Task errors that carry a source position; every other batch-simulate task
# error is exactly ``{"error", "message"}``.
_POSITIONED_ERROR_NAMES = ("parse_error", "validation_error")


class DocumentError(Exception):
    """A document failed a syntax, structural, type or range rule.

    The command layer maps the same exception to family-specific error
    names (``sample_input_error``, ``batch_input_error``,
    ``reconcile_input_error``); the message text is already final.
    """


def is_json_int(value: object) -> bool:
    """True for JSON integers (``bool`` is a subclass of int but not one)."""
    return isinstance(value, int) and not isinstance(value, bool)


def _pairs_no_dupes(pairs: list[tuple[str, object]], noun: str) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            raise DocumentError(f"duplicate key {key!r} in {noun}")
        result[key] = value
    return result


def _reject_constant(noun: str):
    def reject(value: str) -> None:
        # json accepts NaN/Infinity by default; they are not valid JSON numbers.
        raise DocumentError(f"{noun} contains non-JSON constant {value!r}")

    return reject


def load_json(text: str, noun: str) -> object:
    """Parse strict JSON for the document family named *noun*.

    *noun* is the exact phrase used in diagnostics ("samples document",
    "batch manifest", "baseline"). Duplicate keys and non-JSON constants
    raise :class:`DocumentError`; plain syntax errors propagate as
    :class:`json.JSONDecodeError` so callers can apply the family's own
    "is not valid JSON" prefix.
    """
    return json.loads(
        text,
        object_pairs_hook=lambda pairs: _pairs_no_dupes(pairs, noun),
        parse_constant=_reject_constant(noun),
    )


# --------------------------------------------------------------- samples doc


def parse_samples_document(text: str, num_clbits: int) -> dict[str, int]:
    """Validate the samples document, returning its counts mapping.

    Every structural, type and width rule is checked here, before any
    state is evolved. Raises :class:`DocumentError` on the first problem.
    """
    try:
        data = load_json(text, "samples document")
    except json.JSONDecodeError as exc:
        raise DocumentError(f"samples document is not valid JSON: {exc}") from None

    if not isinstance(data, dict):
        raise DocumentError("samples document must be a JSON object")
    for key in data:
        if key not in _VERIFY_SAMPLES_ROOT_KEYS:
            raise DocumentError(f"unknown samples key {key!r}")

    if "schema_version" not in data:
        raise DocumentError("samples document is missing required key 'schema_version'")
    schema_version = data["schema_version"]
    if not is_json_int(schema_version) or schema_version != 1:
        raise DocumentError(f"samples schema_version must be 1, got {schema_version!r}")

    if "counts" not in data:
        raise DocumentError("samples document is missing required key 'counts'")
    counts = data["counts"]
    if not isinstance(counts, dict) or not counts:
        raise DocumentError("samples 'counts' must be a non-empty JSON object")
    for key, value in counts.items():
        if len(key) != num_clbits or any(bit not in "01" for bit in key):
            raise DocumentError(
                f"samples 'counts' key {key!r} is not a {num_clbits}-bit measurement string"
            )
        if not is_json_int(value) or value <= 0:
            raise DocumentError("samples 'counts' values must be positive integers")
    return counts


# -------------------------------------------------------------- batch manifest


def validate_batch_manifest(data: object) -> list[dict[str, object]]:
    """Validate the parsed manifest, returning the raw jobs in list order.

    Every structural, type and range rule is checked here, before any task
    file is read. Raises :class:`DocumentError` on the first problem.
    """
    if not isinstance(data, dict):
        raise DocumentError("batch manifest must be a JSON object")

    for key in data:
        if key not in _BATCH_ROOT_KEYS:
            raise DocumentError(f"unknown batch manifest key {key!r}")

    if "schema_version" not in data:
        raise DocumentError("batch manifest is missing required key 'schema_version'")
    schema_version = data["schema_version"]
    if not is_json_int(schema_version) or schema_version != BATCH_SCHEMA_VERSION:
        raise DocumentError(
            f"batch manifest schema_version must be {BATCH_SCHEMA_VERSION}, got {schema_version!r}"
        )

    if "jobs" not in data:
        raise DocumentError("batch manifest is missing required key 'jobs'")
    jobs = data["jobs"]
    if not isinstance(jobs, list):
        raise DocumentError("batch manifest 'jobs' must be an array")
    if not 1 <= len(jobs) <= MAX_BATCH_JOBS:
        raise DocumentError(
            f"batch manifest 'jobs' must contain between 1 and {MAX_BATCH_JOBS} jobs, got {len(jobs)}"
        )

    seen_ids: set[str] = set()
    for index, job in enumerate(jobs):
        where = f"job at jobs[{index}]"
        if not isinstance(job, dict):
            raise DocumentError(f"{where} must be a JSON object")
        for key in job:
            if key not in _BATCH_JOB_KEYS:
                raise DocumentError(f"{where} has unknown key {key!r}")

        if "id" not in job:
            raise DocumentError(f"{where} is missing required key 'id'")
        job_id = job["id"]
        if not isinstance(job_id, str) or not job_id:
            raise DocumentError(f"{where} 'id' must be a non-empty string")
        if job_id in seen_ids:
            raise DocumentError(f"duplicate job id {job_id!r}")
        seen_ids.add(job_id)

        if "source" not in job:
            raise DocumentError(f"{where} is missing required key 'source'")
        source = job["source"]
        if not isinstance(source, str):
            raise DocumentError(f"{where} 'source' must be a string")
        if source == "-":
            raise DocumentError(f"{where} 'source' must not be '-'; stdin is reserved for the manifest")

        if "shots" in job:
            shots = job["shots"]
            if not is_json_int(shots) or shots <= 0:
                raise DocumentError(f"{where} 'shots' must be a positive integer")

        if "seed" in job and not is_json_int(job["seed"]):
            raise DocumentError(f"{where} 'seed' must be an integer")

        if "noise_model" in job:
            noise_model = job["noise_model"]
            if not isinstance(noise_model, str):
                raise DocumentError(f"{where} 'noise_model' must be a string path")
            if noise_model == "-":
                raise DocumentError(
                    f"{where} 'noise_model' must not be '-'; stdin is reserved for the manifest"
                )

    return jobs


# ------------------------------------------------------------------ baselines


def _require_int(value: object, description: str) -> int:
    if not is_json_int(value):
        raise DocumentError(f"{description} must be an integer")
    return value


def check_finite_numbers(value: object, description: str) -> None:
    """Reject non-finite floats anywhere in an already-parsed JSON payload.

    Integers, strings, booleans and ``None`` are unproblematic; floats are
    only reachable through explicit decimal literals (constants such as
    ``NaN`` are refused at parse time) but must still be finite.
    """
    if isinstance(value, float):
        if not math.isfinite(value):
            raise DocumentError(f"{description} is not a finite number")
    elif isinstance(value, dict):
        for key, item in value.items():
            check_finite_numbers(item, f"{description}.{key}")
    elif isinstance(value, list):
        for index, item in enumerate(value):
            check_finite_numbers(item, f"{description}[{index}]")


def _validate_baseline_output(output: object, where: str) -> dict[str, object]:
    if not isinstance(output, dict):
        raise DocumentError(f"{where} must be a JSON object")
    for key in output:
        if key not in _OUTPUT_V2_KEYS:
            raise DocumentError(f"{where} has unknown key {key!r}")

    for required in _OUTPUT_V1_KEYS:
        if required not in output:
            raise DocumentError(f"{where} is missing required key {required!r}")

    schema_version = _require_int(output["schema_version"], f"{where} 'schema_version'")
    shots = _require_int(output["shots"], f"{where} 'shots'")
    _require_int(output["seed"], f"{where} 'seed'")
    num_qubits = _require_int(output["num_qubits"], f"{where} 'num_qubits'")
    num_clbits = _require_int(output["num_clbits"], f"{where} 'num_clbits'")

    if schema_version not in (1, 2):
        raise DocumentError(f"{where} 'schema_version' must be 1 or 2")
    if shots <= 0:
        raise DocumentError(f"{where} 'shots' must be a positive integer")
    if not 1 <= num_qubits <= 20:
        raise DocumentError(f"{where} 'num_qubits' must be between 1 and 20")
    if not 1 <= num_clbits <= 20:
        raise DocumentError(f"{where} 'num_clbits' must be between 1 and 20")

    counts = output["counts"]
    if not isinstance(counts, dict) or not counts:
        raise DocumentError(f"{where} 'counts' must be a non-empty JSON object")
    total = 0
    for key, value in counts.items():
        if not isinstance(key, str) or not key:
            raise DocumentError(f"{where} 'counts' keys must be non-empty strings")
        if not is_json_int(value) or value <= 0:
            raise DocumentError(f"{where} 'counts' values must be positive integers")
        if len(key) != num_clbits or any(bit not in "01" for bit in key):
            raise DocumentError(
                f"{where} 'counts' key {key!r} is not a {num_clbits}-bit measurement string"
            )
        total += value
    if total != shots:
        raise DocumentError(f"{where} 'counts' must sum to shots ({shots}), got {total}")

    if schema_version == 2:
        if num_qubits > MAX_NOISE_QUBITS:
            raise DocumentError(
                f"{where} noisy output must have at most {MAX_NOISE_QUBITS} qubits"
            )
        if "noise_model" not in output:
            raise DocumentError(f"{where} is missing required key 'noise_model'")
        noise_model = output["noise_model"]
        if not isinstance(noise_model, dict) or not noise_model:
            raise DocumentError(f"{where} 'noise_model' must be a non-empty JSON object")
        for channel, probability in noise_model.items():
            if channel not in _NOISE_CHANNELS:
                raise DocumentError(f"{where} has unknown noise channel {channel!r}")
            if isinstance(probability, bool) or not isinstance(probability, (int, float)):
                raise DocumentError(f"{where} noise channel {channel!r} must be a number")
            if not math.isfinite(float(probability)) or not 0.0 <= float(probability) <= 1.0:
                raise DocumentError(
                    f"{where} noise channel {channel!r} probability must be between 0 and 1"
                )
    elif "noise_model" in output:
        raise DocumentError(f"{where} schema_version 1 output must not contain 'noise_model'")

    return output


def _validate_baseline_error(error: object, where: str) -> dict[str, object]:
    if not isinstance(error, dict):
        raise DocumentError(f"{where} must be a JSON object")
    for key in error:
        if key not in _ERROR_KEYS:
            raise DocumentError(f"{where} has unknown key {key!r}")

    name = error.get("error")
    if not isinstance(name, str) or name not in _RECONCILE_ERROR_NAMES:
        raise DocumentError(f"{where} 'error' must name a batch-simulate task error")
    if "message" not in error or not isinstance(error["message"], str):
        raise DocumentError(f"{where} is missing a string 'message'")

    if name in _POSITIONED_ERROR_NAMES:
        for position in ("line", "column"):
            if position not in error:
                raise DocumentError(f"{where} is missing required key {position!r}")
            value = error[position]
            if not is_json_int(value) or value < 1:
                raise DocumentError(f"{where} {position!r} must be a positive integer")
    elif "line" in error or "column" in error:
        raise DocumentError(f"{where} {name!r} errors must not carry a source position")

    return error


def validate_baseline(data: object, jobs: list[dict[str, object]]) -> list[dict[str, object]]:
    """Validate the batch-result *data* against the manifest *jobs*.

    Self-consistency and correspondence (count, ids, order) are checked
    here, before any task is re-run. Raises :class:`DocumentError`.
    """
    if not isinstance(data, dict):
        raise DocumentError("baseline must be a JSON object")
    for key in data:
        if key not in _BASELINE_ROOT_KEYS:
            raise DocumentError(f"unknown baseline key {key!r}")
    if any(key not in data for key in _BASELINE_ROOT_KEYS):
        raise DocumentError("baseline is missing one or more required root keys")

    schema_version = _require_int(data["schema_version"], "baseline 'schema_version'")
    if schema_version != BATCH_SCHEMA_VERSION:
        raise DocumentError(
            f"baseline schema_version must be {BATCH_SCHEMA_VERSION}, got {schema_version!r}"
        )

    job_count = _require_int(data["job_count"], "baseline 'job_count'")
    succeeded = _require_int(data["succeeded"], "baseline 'succeeded'")
    failed = _require_int(data["failed"], "baseline 'failed'")
    if job_count < 0 or succeeded < 0 or failed < 0:
        raise DocumentError("baseline counters must be non-negative")
    if succeeded + failed != job_count:
        raise DocumentError("baseline 'succeeded' + 'failed' must equal 'job_count'")
    if job_count != len(jobs):
        raise DocumentError(
            f"baseline job_count {job_count} does not match manifest job count {len(jobs)}"
        )

    results = data["results"]
    if not isinstance(results, list):
        raise DocumentError("baseline 'results' must be an array")
    if len(results) != job_count:
        raise DocumentError("baseline 'results' length must equal 'job_count'")

    seen: set[str] = set()
    actual_succeeded = 0
    for index, entry in enumerate(results):
        where = f"baseline result[{index}]"
        if not isinstance(entry, dict):
            raise DocumentError(f"{where} must be a JSON object")
        for key in entry:
            if key not in _BASELINE_RESULT_KEYS:
                raise DocumentError(f"{where} has unknown key {key!r}")

        if "id" not in entry:
            raise DocumentError(f"{where} is missing required key 'id'")
        job_id = entry["id"]
        if not isinstance(job_id, str) or not job_id:
            raise DocumentError(f"{where} 'id' must be a non-empty string")
        if job_id in seen:
            raise DocumentError(f"duplicate baseline result id {job_id!r}")
        seen.add(job_id)
        if job_id != jobs[index]["id"]:
            raise DocumentError(
                f"{where} id {job_id!r} does not match manifest id {jobs[index]['id']!r}"
            )

        if "status" not in entry:
            raise DocumentError(f"{where} is missing required key 'status'")
        status = entry["status"]
        if status == "succeeded":
            if "output" not in entry:
                raise DocumentError(f"{where} succeeded result is missing 'output'")
            if "error" in entry:
                raise DocumentError(f"{where} succeeded result must not contain 'error'")
            _validate_baseline_output(entry["output"], f"{where} output")
            actual_succeeded += 1
        elif status == "failed":
            if "error" not in entry:
                raise DocumentError(f"{where} failed result is missing 'error'")
            if "output" in entry:
                raise DocumentError(f"{where} failed result must not contain 'output'")
            _validate_baseline_error(entry["error"], f"{where} error")
        else:
            raise DocumentError(f"{where} 'status' must be 'succeeded' or 'failed'")

        required_keys = (
            {"id", "status", "output"} if status == "succeeded" else {"id", "status", "error"}
        )
        if set(entry) != required_keys:
            raise DocumentError(f"{where} has unexpected keys for status {status!r}")

    if actual_succeeded != succeeded or len(results) - actual_succeeded != failed:
        raise DocumentError("baseline counters do not match result statuses")

    return results


def json_equal(expected: object, actual: object) -> bool:
    """Compare parsed JSON ignoring object key order and whitespace.

    Array order and scalar values (including int-vs-float distinctions and
    numeric precision) are significant.
    """
    if isinstance(expected, dict) and isinstance(actual, dict):
        if set(expected) != set(actual):
            return False
        return all(json_equal(expected[key], actual[key]) for key in expected)
    if isinstance(expected, list) and isinstance(actual, list):
        return len(expected) == len(actual) and all(
            json_equal(left, right) for left, right in zip(expected, actual)
        )
    return expected == actual and type(expected) is type(actual)

"""Pauli-product observable expectation values.

Used by the ``expectation`` subcommand, which evaluates a list of Pauli
products against the final pre-measurement state. Each observable is a
tensor product of single-qubit Pauli operators; qubits not listed are
acted on by the identity, and an empty operator list is the global
identity. Expectations follow ``Tr(rho P)`` (the state-vector path uses
``<psi|P|psi>``), so they live in ``[-1, 1]``.

The observables document is UTF-8 JSON with the same deterministic,
strict structural style as the other JSON inputs: duplicate keys,
unknown keys, type substitutions (including booleans posing as
integers) and out-of-range counts are all rejected.
"""

from __future__ import annotations

import json
import math

OBSERVABLES_SCHEMA_VERSION = 1
MAX_OBSERVABLES = 100

# Expectations this close to an endpoint are reported as the endpoint.
EXPECTATION_TOLERANCE = 1e-15

_OBSERVABLES_ROOT_KEYS = ("schema_version", "observables")
_OBSERVABLE_KEYS = ("id", "operators")
_OPERATOR_KEYS = ("qubit", "pauli")
_PAULIS = ("X", "Y", "Z")


class ObservableError(Exception):
    """The observables document is invalid (``observable_error``)."""


def _is_json_int(value: object) -> bool:
    # bool is a subclass of int but is not a JSON integer here.
    return isinstance(value, int) and not isinstance(value, bool)


def _reject_constant(value: str) -> None:
    # json accepts NaN/Infinity by default; they are not valid JSON numbers.
    raise ObservableError(f"observables document contains non-JSON constant {value!r}")


def _object_pairs(pairs: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            raise ObservableError(f"duplicate key {key!r} in observables document")
        result[key] = value
    return result


def parse_observables(
    text: str, num_qubits: int
) -> list[tuple[str, list[tuple[int, str]]]]:
    """Parse and validate an observables JSON document.

    Returns the observables in input order as ``(id, operators)`` pairs,
    where each operator is a ``(qubit, pauli)`` tuple. *num_qubits* is the
    parsed circuit's register size and bounds every operator qubit. Raises
    :class:`ObservableError` on any syntax, structural, type or range
    problem.
    """
    try:
        data = json.loads(
            text, object_pairs_hook=_object_pairs, parse_constant=_reject_constant
        )
    except json.JSONDecodeError as exc:
        raise ObservableError(f"observables document is not valid JSON: {exc}") from None

    if not isinstance(data, dict):
        raise ObservableError("observables document must be a JSON object")
    for key in data:
        if key not in _OBSERVABLES_ROOT_KEYS:
            raise ObservableError(f"unknown observables document key {key!r}")

    if "schema_version" not in data:
        raise ObservableError("observables document is missing required key 'schema_version'")
    schema_version = data["schema_version"]
    if not _is_json_int(schema_version) or schema_version != OBSERVABLES_SCHEMA_VERSION:
        raise ObservableError(
            f"observables schema_version must be {OBSERVABLES_SCHEMA_VERSION}, "
            f"got {schema_version!r}"
        )

    if "observables" not in data:
        raise ObservableError("observables document is missing required key 'observables'")
    observables = data["observables"]
    if not isinstance(observables, list):
        raise ObservableError("'observables' must be an array")
    if not 1 <= len(observables) <= MAX_OBSERVABLES:
        raise ObservableError(
            f"'observables' must contain between 1 and {MAX_OBSERVABLES} entries, "
            f"got {len(observables)}"
        )

    parsed: list[tuple[str, list[tuple[int, str]]]] = []
    seen_ids: set[str] = set()
    for index, item in enumerate(observables):
        where = f"observables[{index}]"
        if not isinstance(item, dict):
            raise ObservableError(f"{where} must be a JSON object")
        for key in item:
            if key not in _OBSERVABLE_KEYS:
                raise ObservableError(f"{where} has unknown key {key!r}")

        if "id" not in item:
            raise ObservableError(f"{where} is missing required key 'id'")
        observable_id = item["id"]
        if not isinstance(observable_id, str) or not observable_id:
            raise ObservableError(f"{where} 'id' must be a non-empty string")
        if observable_id in seen_ids:
            raise ObservableError(f"duplicate observable id {observable_id!r}")
        seen_ids.add(observable_id)

        if "operators" not in item:
            raise ObservableError(f"{where} is missing required key 'operators'")
        operators = item["operators"]
        if not isinstance(operators, list):
            raise ObservableError(f"{where} 'operators' must be an array")

        parsed_operators: list[tuple[int, str]] = []
        seen_qubits: set[int] = set()
        for op_index, operator in enumerate(operators):
            op_where = f"{where}.operators[{op_index}]"
            if not isinstance(operator, dict):
                raise ObservableError(f"{op_where} must be a JSON object")
            for key in operator:
                if key not in _OPERATOR_KEYS:
                    raise ObservableError(f"{op_where} has unknown key {key!r}")

            if "qubit" not in operator:
                raise ObservableError(f"{op_where} is missing required key 'qubit'")
            qubit = operator["qubit"]
            if not _is_json_int(qubit) or not 0 <= qubit < num_qubits:
                raise ObservableError(
                    f"{op_where} 'qubit' must be an integer between 0 and {num_qubits - 1}, "
                    f"got {qubit!r}"
                )
            if qubit in seen_qubits:
                raise ObservableError(f"{op_where} repeats qubit {qubit} within {where}")
            seen_qubits.add(qubit)

            if "pauli" not in operator:
                raise ObservableError(f"{op_where} is missing required key 'pauli'")
            pauli = operator["pauli"]
            if pauli not in _PAULIS:
                raise ObservableError(
                    f"{op_where} 'pauli' must be one of 'X', 'Y', 'Z', got {pauli!r}"
                )

            parsed_operators.append((qubit, pauli))
        parsed.append((observable_id, parsed_operators))

    return parsed


def snap_expectation(value: float) -> float | int:
    """Snap one expectation for deterministic, in-range output.

    Values no more than :data:`EXPECTATION_TOLERANCE` from zero become
    ``0.0``; values within that distance of -1 or 1 become the integers
    ``-1``/``1``. Other values are clamped to ``[-1, 1]`` so finite
    precision round-off can never report an out-of-range expectation.
    """
    value = min(1.0, max(-1.0, float(value)))
    if abs(value) <= EXPECTATION_TOLERANCE:
        return 0.0
    if abs(value - 1.0) <= EXPECTATION_TOLERANCE:
        return 1
    if abs(value + 1.0) <= EXPECTATION_TOLERANCE:
        return -1
    return value


def _phase_bits(operators: list[tuple[int, str]]) -> tuple[int, int, int]:
    """Decompose a Pauli product into (X-bits, Y-bits, Z-bits) masks."""
    x_bits = 0
    y_bits = 0
    z_bits = 0
    for qubit, pauli in operators:
        bit = 1 << qubit
        if pauli == "X":
            x_bits |= bit
        elif pauli == "Y":
            y_bits |= bit
        else:
            z_bits |= bit
    return x_bits, y_bits, z_bits


def _pauli_phase(index: int, parity_bits: int, y_factor: complex) -> complex:
    """Scalar phase of ``P|index>``.

    Z sites contribute ``(-1)**b`` and Y sites contribute
    ``i(-1)**b``; over *m* Y sites the shared ``i**m`` is *y_factor*,
    so the total phase is ``i**m`` times the parity sign over the Z and
    Y sites.
    """
    sign = -1.0 if (index & parity_bits).bit_count() & 1 else 1.0
    return sign * y_factor


# i**m for the Y-site count modulo 4.
_I_POWERS = (1 + 0j, 1j, -1 + 0j, -1j)


def state_vector_expectation(
    state: list[complex], operators: list[tuple[int, str]]
) -> float:
    """Return ``<psi|P|psi>`` for a Pauli product *P*.

    The state is renormalized once (gate evolution drifts the norm by a
    few ulps, mirroring the explicit normalization in the metrics path),
    so the global-identity observable is exactly 1.
    """
    norm = math.sqrt(math.fsum(abs(amplitude) ** 2 for amplitude in state))
    if norm == 0.0:
        return 0.0

    x_bits, y_bits, z_bits = _phase_bits(operators)
    flip_bits = x_bits | y_bits
    parity_bits = z_bits | y_bits

    terms: list[float] = []
    if flip_bits == 0:
        # P is diagonal (only Z/I): P|j> = (-1)^<z,j> |j>.
        for index, amplitude in enumerate(state):
            weight = abs(amplitude) ** 2
            terms.append(
                (-weight if (index & z_bits).bit_count() & 1 else weight) / (norm * norm)
            )
        return math.fsum(terms)

    y_factor = _I_POWERS[y_bits.bit_count() & 3]
    for index, amplitude in enumerate(state):
        phase = _pauli_phase(index, parity_bits, y_factor)
        value = (state[index ^ flip_bits].conjugate() * phase * amplitude) / (norm * norm)
        terms.append(value.real)
    return math.fsum(terms)


def density_matrix_expectation(
    rho: list[list[complex]], operators: list[tuple[int, str]]
) -> float:
    """Return ``Tr(rho P)`` for a Pauli product *P*.

    Uses ``Tr(rho P) = sum_j phase(j) rho[j, j xor F]`` where *F* is the
    bit mask of the X/Y sites; *rho* must already be normalized to unit
    trace.
    """
    x_bits, y_bits, z_bits = _phase_bits(operators)
    flip_bits = x_bits | y_bits
    parity_bits = z_bits | y_bits

    if flip_bits == 0:
        terms: list[float] = []
        for index, row in enumerate(rho):
            diagonal = row[index].real
            terms.append(
                -diagonal if (index & z_bits).bit_count() & 1 else diagonal
            )
        return math.fsum(terms)

    y_factor = _I_POWERS[y_bits.bit_count() & 3]
    terms = []
    for index, row in enumerate(rho):
        phase = _pauli_phase(index, parity_bits, y_factor)
        terms.append((row[index ^ flip_bits] * phase).real)
    return math.fsum(terms)

"""Lexer, parser and semantic validation for the OpenQASM 2.0 subset.

Supported subset::

    OPENQASM 2.0;
    include "qelib1.inc";
    qreg name[positive-size];
    creg name[positive-size];
    x qubit;
    h qubit;
    y qubit;
    z qubit;
    s qubit;
    sdg qubit;
    t qubit;
    tdg qubit;
    cx qubit, qubit;
    cz qubit, qubit;
    swap qubit, qubit;
    rx(angle) qubit;
    ry(angle) qubit;
    rz(angle) qubit;
    crx(angle) qubit, qubit;
    cry(angle) qubit, qubit;
    crz(angle) qubit, qubit;
    measure qubit -> cbit;

Only one ``qreg`` and one ``creg`` may be declared, and gates/measures only
accept single bits with constant integer indices. Line comments (``//``) are
supported.

Angle expressions are written in radians and may use decimal integer and
real literals (including scientific notation), the constant ``pi``,
parentheses, unary ``+``/``-`` and the binary operators ``+``, ``-``, ``*``
and ``/`` with the usual precedence (``*``/``/`` before ``+``/``-``, same
precedence evaluated left to right, parentheses first).
"""

from __future__ import annotations

import math
from dataclasses import dataclass

from .gates import (
    CONTROLLED,
    GATE_SPECS,
    SWAP,
    Operation,
    gate_operation,
    measurement_operation,
)

# Re-exported so modules that already import the validated operation type
# from the parser module keep working; the definition itself lives with the
# authoritative gate semantics in :mod:`quantum_circuit.gates`.
__all__ = ["ParseError", "ValidationError", "Token", "Operation", "Program", "parse", "tokenize"]


class ParseError(Exception):
    """A lexical or syntactic problem (reported as ``parse_error``)."""

    def __init__(self, message: str, line: int, column: int):
        super().__init__(message)
        self.message = message
        self.line = line
        self.column = column


class ValidationError(Exception):
    """A syntactically valid but semantically invalid program."""

    def __init__(self, message: str, line: int, column: int):
        super().__init__(message)
        self.message = message
        self.line = line
        self.column = column


@dataclass(frozen=True)
class Token:
    kind: str  # 'ident', 'int', 'real', 'string' or a literal punctuation word
    value: str
    line: int  # 1-based
    column: int  # 1-based, points at the first character of the token


_KEYWORDS = {"OPENQASM", "include", "qreg", "creg", "measure"}
# Gate names, operand shapes and parameter rules all come from the single
# semantic registry in :mod:`quantum_circuit.gates`.
_BUILTIN_GATES = frozenset(GATE_SPECS)

# A state vector has 2**n amplitudes; larger registers cannot be simulated
# and are rejected as illegal sizes rather than crashing.
_MAX_REGISTER_SIZE = 20


def tokenize(source: str) -> list[Token]:
    """Split *source* into tokens.

    Raises :class:`ParseError` (with 1-based position) on invalid input.
    """
    tokens: list[Token] = []
    line = 1
    col = 1
    n = len(source)
    i = 0

    while i < n:
        ch = source[i]

        if ch == "\n":
            i += 1
            line += 1
            col = 1
            continue
        if ch in " \t\r":
            i += 1
            col += 1
            continue

        # Line comment: runs to end of line (end of input also terminates it).
        if ch == "/" and i + 1 < n and source[i + 1] == "/":
            i += 2
            col += 2
            while i < n and source[i] != "\n":
                i += 1
                col += 1
            continue

        start_line, start_col = line, col

        if ch.isalpha() or ch == "_":
            j = i + 1
            while j < n and (source[j].isalnum() or source[j] == "_"):
                j += 1
            word = source[i:j]
            kind = word if word in _KEYWORDS else "ident"
            tokens.append(Token(kind, word, start_line, start_col))
            col += j - i
            i = j
            continue

        if ch.isdigit() or (ch == "." and i + 1 < n and source[i + 1].isdigit()):
            j = i
            seen_dot = False
            seen_exp = False
            while j < n:
                c = source[j]
                if c.isdigit():
                    j += 1
                elif c == "." and not seen_dot and not seen_exp:
                    seen_dot = True
                    j += 1
                elif c in "eE" and not seen_exp:
                    seen_exp = True
                    j += 1
                    if j < n and source[j] in "+-":
                        j += 1
                else:
                    break
            word = source[i:j]
            kind = "real" if seen_dot or seen_exp else "int"
            tokens.append(Token(kind, word, start_line, start_col))
            col += j - i
            i = j
            continue

        if ch == '"':
            j = i + 1
            while j < n and source[j] != '"':
                if source[j] == "\n":
                    raise ParseError("unterminated string literal", start_line, start_col)
                j += 1
            if j >= n:
                raise ParseError("unterminated string literal", start_line, start_col)
            tokens.append(Token("string", source[i + 1 : j], start_line, start_col))
            col += j - i + 1
            i = j + 1
            continue

        if ch == "-" and i + 1 < n and source[i + 1] == ">":
            tokens.append(Token("->", "->", start_line, start_col))
            i += 2
            col += 2
            continue

        if ch in "[];,()+*/-":
            tokens.append(Token(ch, ch, start_line, start_col))
            i += 1
            col += 1
            continue

        raise ParseError(f"unexpected character {ch!r}", start_line, start_col)

    tokens.append(Token("eof", "", line, col))
    return tokens


@dataclass(frozen=True)
class Program:
    num_qubits: int
    num_clbits: int
    operations: tuple[Operation, ...]


def _parse_decimal(token: Token) -> int:
    """Parse a non-negative decimal literal, rejecting oversized ones."""
    if len(token.value) > 18:
        raise ValidationError("integer literal is too large", token.line, token.column)
    return int(token.value)


def parse(source: str) -> Program:
    """Parse and validate the OpenQASM subset, returning a :class:`Program`."""
    tokens = tokenize(source)
    pos = 0

    def peek() -> Token:
        return tokens[pos]

    def advance() -> Token:
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def expect(kind: str) -> Token:
        tok = peek()
        if tok.kind != kind:
            raise ParseError(f"expected {kind!r} but found {tok.value!r}", tok.line, tok.column)
        return advance()

    # Header: OPENQASM 2.0;  (a real token "2.0", exactly)
    first = peek()
    if first.kind != "OPENQASM":
        raise ParseError("expected 'OPENQASM' declaration", first.line, first.column)
    advance()
    version = expect("real") if peek().kind == "real" else expect("int")
    if version.value != "2.0":
        raise ParseError(f"unsupported OpenQASM version {version.value!r}", version.line, version.column)
    expect(";")

    # Exactly: include "qelib1.inc";
    expect("include")
    path = expect("string")
    if path.value != "qelib1.inc":
        raise ValidationError(f"unknown include file {path.value!r}", path.line, path.column)
    expect(";")

    qreg_name: str | None = None
    qreg_size: int | None = None
    creg_name: str | None = None
    creg_size: int | None = None
    operations: list[Operation] = []
    measured_qubits: set[int] = set()
    measured_clbits: set[int] = set()
    measurement_started = False

    def parse_index(reg_kind: str) -> tuple[int, Token, Token]:
        """Parse ``name[const]`` returning (index, name token, index token)."""
        name_tok = expect("ident")
        expect("[")
        idx_tok = expect("int")
        expect("]")
        if reg_kind == "q":
            if name_tok.value != qreg_name:
                if creg_name is not None and name_tok.value == creg_name:
                    raise ValidationError(
                        "classical register used where a quantum register is required",
                        name_tok.line,
                        name_tok.column,
                    )
                raise ValidationError(
                    f"undeclared quantum register {name_tok.value!r}",
                    name_tok.line,
                    name_tok.column,
                )
            size = qreg_size
        else:
            if name_tok.value != creg_name:
                if qreg_name is not None and name_tok.value == qreg_name:
                    raise ValidationError(
                        "quantum register used where a classical register is required",
                        name_tok.line,
                        name_tok.column,
                    )
                raise ValidationError(
                    f"undeclared classical register {name_tok.value!r}",
                    name_tok.line,
                    name_tok.column,
                )
            size = creg_size
        idx = _parse_decimal(idx_tok)
        assert size is not None
        if not 0 <= idx < size:
            raise ValidationError(
                f"register index {idx} out of range for register of size {size}",
                idx_tok.line,
                idx_tok.column,
            )
        return idx, name_tok, idx_tok

    def parse_angle() -> float:
        """Parse and evaluate an angle expression (result in radians).

        Grammar (usual precedence, left associativity, parentheses first)::

            expr    := term (('+' | '-') term)*
            term    := factor (('*' | '/') factor)*
            factor  := ('+' | '-') factor | atom
            atom    := int | real | 'pi' | '(' expr ')'
        """

        def check_finite(value: float, op_tok: Token) -> float:
            if not math.isfinite(value):
                raise ValidationError(
                    "angle expression result is not a finite number",
                    op_tok.line,
                    op_tok.column,
                )
            return value

        def parse_atom() -> float:
            tok = peek()
            if tok.kind == "int":
                advance()
                return float(_parse_decimal(tok))
            if tok.kind == "real":
                advance()
                try:
                    value = float(tok.value)
                except ValueError:
                    raise ParseError(
                        f"malformed numeric literal {tok.value!r}",
                        tok.line,
                        tok.column,
                    ) from None
                if not math.isfinite(value):
                    raise ValidationError(
                        f"numeric literal {tok.value!r} is too large",
                        tok.line,
                        tok.column,
                    )
                return value
            if tok.kind == "ident":
                advance()
                if tok.value == "pi":
                    return math.pi
                raise ValidationError(
                    f"unknown name {tok.value!r} in angle expression",
                    tok.line,
                    tok.column,
                )
            if tok.kind == "(":
                advance()
                value = parse_expr()
                expect(")")
                return value
            raise ParseError(
                f"expected a number, 'pi' or '(' but found {tok.value!r}",
                tok.line,
                tok.column,
            )

        def parse_factor() -> float:
            tok = peek()
            if tok.kind == "+" or tok.kind == "-":
                advance()
                operand = parse_factor()
                return operand if tok.kind == "+" else -operand
            return parse_atom()

        def parse_term() -> float:
            value = parse_factor()
            while peek().kind == "*" or peek().kind == "/":
                op_tok = advance()
                rhs = parse_factor()
                if op_tok.kind == "*":
                    value = check_finite(value * rhs, op_tok)
                else:
                    if rhs == 0.0:
                        raise ValidationError(
                            "division by zero in angle expression",
                            op_tok.line,
                            op_tok.column,
                        )
                    value = check_finite(value / rhs, op_tok)
            return value

        def parse_expr() -> float:
            value = parse_term()
            while peek().kind == "+" or peek().kind == "-":
                op_tok = advance()
                rhs = parse_term()
                if op_tok.kind == "+":
                    value = check_finite(value + rhs, op_tok)
                else:
                    value = check_finite(value - rhs, op_tok)
            return value

        return parse_expr()

    while peek().kind != "eof":
        tok = peek()

        if tok.kind == "qreg" or tok.kind == "creg":
            advance()
            is_qreg = tok.kind == "qreg"
            name_tok = expect("ident")
            expect("[")
            size_tok = expect("int")
            expect("]")
            expect(";")
            size = _parse_decimal(size_tok)
            if not 1 <= size <= _MAX_REGISTER_SIZE:
                raise ValidationError(
                    f"register size must be between 1 and {_MAX_REGISTER_SIZE}, got {size}",
                    size_tok.line,
                    size_tok.column,
                )
            if is_qreg:
                if qreg_name is not None:
                    raise ValidationError(
                        "duplicate declaration of quantum register",
                        name_tok.line,
                        name_tok.column,
                    )
                if creg_name is not None and name_tok.value == creg_name:
                    raise ValidationError(
                        f"register name {name_tok.value!r} already declared",
                        name_tok.line,
                        name_tok.column,
                    )
                qreg_name = name_tok.value
                qreg_size = size
            else:
                if creg_name is not None:
                    raise ValidationError(
                        "duplicate declaration of classical register",
                        name_tok.line,
                        name_tok.column,
                    )
                if qreg_name is not None and name_tok.value == qreg_name:
                    raise ValidationError(
                        f"register name {name_tok.value!r} already declared",
                        name_tok.line,
                        name_tok.column,
                    )
                creg_name = name_tok.value
                creg_size = size
            continue

        if tok.kind == "measure":
            advance()
            q_idx, q_name_tok, _q_idx_tok = parse_index("q")
            expect("->")
            c_idx, c_name_tok, _c_idx_tok = parse_index("c")
            expect(";")
            if q_idx in measured_qubits:
                raise ValidationError(
                    f"qubit {qreg_name}[{q_idx}] is measured more than once",
                    q_name_tok.line,
                    q_name_tok.column,
                )
            if c_idx in measured_clbits:
                raise ValidationError(
                    f"clbit {creg_name}[{c_idx}] is the target of more than one measurement",
                    c_name_tok.line,
                    c_name_tok.column,
                )
            measured_qubits.add(q_idx)
            measured_clbits.add(c_idx)
            measurement_started = True
            operations.append(measurement_operation(q_idx, c_idx))
            continue

        if tok.kind == "ident":
            gate_name = tok.value
            if gate_name not in _BUILTIN_GATES:
                raise ValidationError(
                    f"undeclared identifier or unsupported gate {gate_name!r}",
                    tok.line,
                    tok.column,
                )
            if measurement_started:
                raise ValidationError(
                    f"quantum gate {gate_name!r} appears after a measurement",
                    tok.line,
                    tok.column,
                )
            advance()
            spec = GATE_SPECS[gate_name]
            if spec.parameterized:
                expect("(")
                angle = parse_angle()
                if peek().kind == ",":
                    comma = peek()
                    raise ParseError(
                        f"gate {gate_name!r} takes exactly one angle parameter",
                        comma.line,
                        comma.column,
                    )
                expect(")")
            if spec.style == CONTROLLED:
                ctrl, _, _ = parse_index("q")
                expect(",")
                tgt, tgt_name_tok, _ = parse_index("q")
                expect(";")
                if ctrl == tgt:
                    raise ValidationError(
                        f"{gate_name} control and target must be different qubits",
                        tgt_name_tok.line,
                        tgt_name_tok.column,
                    )
                targets = (ctrl, tgt)
            elif spec.style == SWAP:
                first, _, _ = parse_index("q")
                expect(",")
                second, second_name_tok, _ = parse_index("q")
                expect(";")
                if first == second:
                    raise ValidationError(
                        f"{gate_name} operands must be different qubits",
                        second_name_tok.line,
                        second_name_tok.column,
                    )
                targets = (first, second)
            else:
                target, _, _ = parse_index("q")
                expect(";")
                targets = (target,)
            params = (angle,) if spec.parameterized else ()
            operations.append(gate_operation(gate_name, targets, params))
            continue

        raise ParseError(
            f"unexpected token {tok.value!r}",
            tok.line,
            tok.column,
        )

    eof = peek()
    if qreg_name is None:
        raise ValidationError("missing required quantum register declaration", eof.line, eof.column)
    if creg_name is None:
        raise ValidationError("missing required classical register declaration", eof.line, eof.column)

    return Program(
        num_qubits=qreg_size if qreg_size is not None else 0,
        num_clbits=creg_size if creg_size is not None else 0,
        operations=tuple(operations),
    )
